window.DP700_DUMP = {"meta":{"title":"DP-700 Validated Question Report","questionCount":118,"correctSelections":88,"correctedSelections":30,"validatedThrough":"18 July 2026","notice":"Imported from the supplied validation report. Product behavior may change; use linked Microsoft sources as the current authority."},"sources":[{"id":"R1","title":"DP-700 study guide and current skills measured","url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/dp-700"},{"id":"R2","title":"High-concurrency Spark sessions","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/configure-high-concurrency-session-notebooks"},{"id":"R3","title":"Lakehouse sharing and permissions","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/lakehouse-sharing"},{"id":"R4","title":"Git integration in Microsoft Fabric","url":"https://learn.microsoft.com/en-us/fabric/cicd/git-integration/intro-to-git-integration"},{"id":"R5","title":"Direct Lake overview and capacity considerations","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-overview"},{"id":"R6","title":"Dimensional modeling in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-overview"},{"id":"R7","title":"Row-level security in Fabric data warehousing","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/row-level-security"},{"id":"R8","title":"Introduction to Fabric deployment pipelines","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines"},{"id":"R9","title":"Deployment pipeline deployment behavior","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/understand-the-deployment-process"},{"id":"R10","title":"SQL database projects","url":"https://learn.microsoft.com/en-us/sql/tools/sql-database-projects/sql-database-projects?view=sql-server-ver17"},{"id":"R11","title":"Eventhouse OneLake availability","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-house-onelake-availability"},{"id":"R12","title":"OneLake shortcuts and shortcut cache","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-shortcuts"},{"id":"R13","title":"Fabric managed private endpoints","url":"https://learn.microsoft.com/en-us/fabric/security/security-managed-private-endpoints-overview"},{"id":"R14","title":"OneLake events and Activator actions","url":"https://learn.microsoft.com/en-us/fabric/real-time-hub/set-alerts-fabric-onelake-events"},{"id":"R15","title":"Fabric domains","url":"https://learn.microsoft.com/en-us/fabric/governance/domains"},{"id":"R16","title":"Granular SQL permissions in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/sql-granular-permissions"},{"id":"R17","title":"Endorsement in Fabric and Power BI","url":"https://learn.microsoft.com/en-us/fabric/governance/endorsement-overview"},{"id":"R18","title":"Fabric environment library management","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/library-management"},{"id":"R19","title":"Lakehouse Delta table maintenance","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/lakehouse-table-maintenance"},{"id":"R20","title":"Fabric Monitoring hub","url":"https://learn.microsoft.com/en-us/fabric/admin/monitoring-hub"},{"id":"R21","title":"Primary, foreign, and unique keys in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/table-constraints"},{"id":"R22","title":"Semantic Link overview","url":"https://learn.microsoft.com/en-us/fabric/data-science/semantic-link-overview"},{"id":"R23","title":"KQL sort operator","url":"https://learn.microsoft.com/en-us/kusto/query/sort-operator?view=microsoft-fabric"},{"id":"R24","title":"Notebook utilities, including credentials and notebook orchestration","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/notebook-utilities"},{"id":"R25","title":"Pipeline expression language","url":"https://learn.microsoft.com/en-us/fabric/data-factory/expression-language"},{"id":"R26","title":"Dynamic data masking in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dynamic-data-masking"},{"id":"R27","title":"Column-level security in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/column-level-security"},{"id":"R28","title":"Pipeline runs, schedules, and event triggers","url":"https://learn.microsoft.com/en-us/fabric/data-factory/pipeline-runs"},{"id":"R29","title":"Eventstream overview","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/overview"},{"id":"R30","title":"Eventstream transforms and routing to a lakehouse","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/transform-and-stream-real-time-events-to-lakehouse"},{"id":"R31","title":"Incremental refresh for Dataflow Gen2","url":"https://learn.microsoft.com/en-us/fabric/data-factory/dataflow-gen2-incremental-refresh"},{"id":"R32","title":"Medallion lakehouse architecture","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-medallion-lakehouse-architecture"},{"id":"R33","title":"Eventstream settings and retention","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/configure-settings"},{"id":"R34","title":"KQL update policy","url":"https://learn.microsoft.com/en-us/kusto/management/update-policy?view=microsoft-fabric"},{"id":"R35","title":"Copy activity in Fabric Data Factory","url":"https://learn.microsoft.com/en-us/fabric/data-factory/copy-data-activity"},{"id":"R36","title":"Window transformation support note for Dataflow Gen2","url":"https://learn.microsoft.com/en-us/azure/data-factory/data-flow-window"},{"id":"R37","title":"Delta Lake merge patterns","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/merge-data"},{"id":"R38","title":"Azure SQL CDC source for Eventstream","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/add-source-azure-sql-database-change-data-capture"},{"id":"R39","title":"Query Insights in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/query-insights"},{"id":"R40","title":"Frequently run queries view","url":"https://learn.microsoft.com/en-us/sql/relational-databases/system-views/queryinsights-frequently-run-queries-transact-sql?view=fabric"},{"id":"R41","title":"Apache Spark application monitoring","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/spark-detail-monitoring"},{"id":"R42","title":"Extended Apache Spark history server","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/apache-spark-history-server"},{"id":"R43","title":"Eventstream monitoring","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/monitor"},{"id":"R44","title":"Data Warehouse Monitor","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/monitor"},{"id":"R45","title":"IDENTITY columns in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/identity"},{"id":"R46","title":"Delta optimization and V-Order","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/delta-optimization-and-v-order"},{"id":"R47","title":"Fabric Warehouse performance guidelines","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/guidelines-warehouse-performance"},{"id":"R48","title":"Semantic model refresh pipeline activity","url":"https://learn.microsoft.com/en-us/fabric/data-factory/semantic-model-refresh-activity"},{"id":"R49","title":"Eventstream sources and HTTP connector","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/add-manage-eventstream-sources"},{"id":"R50","title":"Monitor warehouse sessions and requests with DMVs","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/monitor-using-dmv"}],"questions":[{"n":1,"batch":1,"question":"You need to ensure that processes for the bronze and silver layers run in isolation.\nHow should you configure the Apache Spark settings?\n\nA. Disable high concurrency.\nB. Create a custom pool.\nC. Modify the number of executors.\nD. Set the default environment.","options":[{"label":"A","text":"Disable high concurrency."},{"label":"B","text":"Create a custom pool."},{"label":"C","text":"Modify the number of executors."},{"label":"D","text":"Set the default environment."}],"originalAnswer":"B","correctAnswer":"A. Disable high concurrency.","status":"Wrong","explanation":"High concurrency lets eligible notebooks share a Spark session. Because the bronze and silver processes must be isolated from one another, disable high concurrency; a custom pool changes compute sizing/configuration but does not provide notebook-session isolation.","conceptArea":"Implement/manage – Spark compute","notes":[],"refs":["R2"]},{"n":2,"batch":1,"question":"DRAG DROP (Drag and Drop is not supported)\nYou need to ensure that the authors can see only their respective sales data.\nHow should you complete the statement? To answer, drag the appropriate values the correct targets.\nEach value may be used once, more than once, or not at all. You may need to drag the split bar between\npanes or scroll to view content.\nNote: Each correct selection is worth one point.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"SCHEMABINDING; USER_NAME(); AuthorSales","correctAnswer":"WITH SCHEMABINDING; USER_NAME(); apply the predicate to AuthorSales.","status":"Correct","explanation":"Fabric Warehouse RLS uses an inline table-valued predicate function and a security policy. SCHEMABINDING binds the function, USER_NAME() supplies the signed-in database principal, and the predicate must be attached to AuthorSales.","conceptArea":"Implement/manage – Security (RLS)","notes":[],"refs":["R7"]},{"n":3,"batch":1,"question":"You need to ensure that the data analysts can access the gold layer lakehouse.\nWhat should you do?\n\nA. Add the DataAnalyst group to the Viewer role for WorkspaceA.\nB. Share the lakehouse with the DataAnalysts group and grant the Build reports on the default semantic\nmodel permission.\nC. Share the lakehouse with the DataAnalysts group and grant the Read all SQL Endpoint data\npermission.\nD. Share the lakehouse with the DataAnalysts group and grant the Read all Apache Spark permission.","options":[{"label":"A","text":"Add the DataAnalyst group to the Viewer role for WorkspaceA."},{"label":"B","text":"Share the lakehouse with the DataAnalysts group and grant the Build reports on the default semantic\nmodel permission."},{"label":"C","text":"Share the lakehouse with the DataAnalysts group and grant the Read all SQL Endpoint data\npermission."},{"label":"D","text":"Share the lakehouse with the DataAnalysts group and grant the Read all Apache Spark permission."}],"originalAnswer":"C","correctAnswer":"C. Share the gold-layer lakehouse and grant Read all SQL endpoint data.","status":"Correct","explanation":"This gives the analysts SQL read access to the lakehouse tables without granting Spark access to underlying files or a workspace role that would expose other items.","conceptArea":"Implement/manage – Lakehouse security","notes":[],"refs":["R3"]},{"n":4,"batch":1,"question":"You need to ensure that WorkspaceA can be configured for source control.\nWhich two actions should you perform? Each correct answer presents part of the solution.\nNote: Each correct selection is worth one point.\n\nA. From Tenant setting, set Users can synchronize workspace items with their Git repositories to Enabled.\nB. From Tenant setting, set Users can sync workspace items with GitHub repositories to Enabled.\nC. Configure WorkspaceA to use a Premium Per User (PPU) license.\nD. Assign WorkspaceA to Cap1.","options":[{"label":"A","text":"From Tenant setting, set Users can synchronize workspace items with their Git repositories to Enabled."},{"label":"B","text":"From Tenant setting, set Users can sync workspace items with GitHub repositories to Enabled."},{"label":"C","text":"Configure WorkspaceA to use a Premium Per User (PPU) license."},{"label":"D","text":"Assign WorkspaceA to Cap1."}],"originalAnswer":"A, D","correctAnswer":"A and D. Enable the tenant Git synchronization setting and assign WorkspaceA to Cap1.","status":"Correct","explanation":"Fabric Git integration requires the tenant setting and a supported Fabric/Premium capacity. Azure Repos uses the general Git synchronization tenant setting; the GitHub-specific switch is not required here.","conceptArea":"Implement/manage – Git and lifecycle","notes":[],"refs":["R4"]},{"n":5,"batch":1,"question":"You have a Fabric workspace.\nYou have semi-structured data.\nYou need to read the data by using T-SQL, KQL, and Apache Spark. The data will only be written by\nusing Spark.\nWhat should you use to store the data?\n\nA. a lakehouse\nB. an eventhouse\n\nC. a datamart\nD. a warehouse","options":[{"label":"A","text":"a lakehouse"},{"label":"B","text":"an eventhouse"},{"label":"C","text":"a datamart"},{"label":"D","text":"a warehouse"}],"originalAnswer":"A","correctAnswer":"A. A lakehouse.","status":"Correct","explanation":"A lakehouse stores semi-structured data in OneLake/Delta, is writable with Spark, and is readable through Spark and the SQL analytics endpoint. Current Fabric can also expose lakehouse data to KQL through an Eventhouse endpoint/OneLake integration, making it the only listed store that fits the cross-engine requirement.","conceptArea":"Ingest/transform – Lakehouse storage","notes":[],"refs":["R11","R12"]},{"n":6,"batch":1,"question":"You have a Fabric workspace that contains a warehouse named Warehouse1.\nYou have an on-premises Microsoft SQL Server database named Database1 that is accessed by using\nan on- premises data gateway.\nYou need to copy data from Database1 to Warehouse1.\nWhich item should you use?\n\nA. a Dataflow Gen1 dataflow\nB. a data pipeline\nC. a KQL queryset\nD. a notebook","options":[{"label":"A","text":"a Dataflow Gen1 dataflow"},{"label":"B","text":"a data pipeline"},{"label":"C","text":"a KQL queryset"},{"label":"D","text":"a notebook"}],"originalAnswer":"B","correctAnswer":"B. A data pipeline.","status":"Correct","explanation":"A Fabric data pipeline Copy activity supports on-premises SQL Server through the on-premises gateway and can write to a Fabric warehouse.","conceptArea":"Ingest/transform – Batch ingestion","notes":[],"refs":["R35"]},{"n":7,"batch":1,"question":"You have a Fabric workspace that contains a warehouse named Warehouse1.\nYou have an on-premises Microsoft SQL Server database named Database1 that is accessed by using\nan on- premises data gateway.\nYou need to copy data from Database1 to Warehouse1.\nWhich item should you use?\n\nA. an Apache Spark job definition\nB. a data pipeline\nC. a Dataflow Gen1 dataflow\nD. an eventstream","options":[{"label":"A","text":"an Apache Spark job definition"},{"label":"B","text":"a data pipeline"},{"label":"C","text":"a Dataflow Gen1 dataflow"},{"label":"D","text":"an eventstream"}],"originalAnswer":"B","correctAnswer":"B. A data pipeline.","status":"Correct","explanation":"The pipeline Copy activity is the supported orchestration and movement item for copying from gateway-accessed SQL Server to a Fabric warehouse.","conceptArea":"Ingest/transform – Batch ingestion","notes":[],"refs":["R35"]},{"n":8,"batch":1,"question":"You have a Fabric F32 capacity that contains a workspace. The workspace contains a warehouse named\nDW1 that is modelled by using MD5 hash surrogate keys.\nDW1 contains a single fact table that has grown from 200 million rows to 500 million rows during the past\nyear.\nYou have Microsoft Power BI reports that are based on Direct Lake. The reports show year-over-year\nvalues.\nUsers report that the performance of some of the reports has degraded over time and some visuals show\nerrors.\nYou need to resolve the performance issues. The solution must meet the following requirements:\nProvide the best query performance.\nMinimize operational costs.\nWhich should you do?\n\nA. Change the MD5 hash to SHA256.\nB. Increase the capacity.\nC. Enable V-Order.\nD. Modify the surrogate keys to use a different data type.\nE. Create views.","options":[{"label":"A","text":"Change the MD5 hash to SHA256."},{"label":"B","text":"Increase the capacity."},{"label":"C","text":"Enable V-Order."},{"label":"D","text":"Modify the surrogate keys to use a different data type."},{"label":"E","text":"Create views."}],"originalAnswer":"B","correctAnswer":"B. Increase the capacity.","status":"Correct","explanation":"The 500-million-row fact table has outgrown the lower-capacity Direct Lake guardrail assumed by the question, which can cause fallback and visual errors. Moving to a capacity with higher Direct Lake limits is the listed action that preserves the best query path; changing the hash algorithm or adding views does not remove that limit.","conceptArea":"Monitor/optimize – Direct Lake capacity","notes":["Capacity guardrails can change; validate the exact SKU limits in the current Direct Lake documentation before sizing production."],"refs":["R5"]},{"n":9,"batch":1,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a warehouse named DW1. DW1 contains the following tables\nand columns.\n\nYou need to create an output that presents the summarized values of all the order quantities by year and\nproduct. The results must include a summary of the order quantities at the year level for all the products.\nHow should you complete the code? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\n\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"YEAR(SO.ModifiedDate); ROLLUP(YEAR(SO.ModifiedDate), P.Name)","correctAnswer":"SELECT YEAR(SO.ModifiedDate); GROUP BY ROLLUP(YEAR(SO.ModifiedDate), P.Name).","status":"Correct","explanation":"YEAR extracts the grouping year. ROLLUP on year then product returns product totals within each year plus the required year-level subtotal (and a grand total).","conceptArea":"Ingest/transform – Warehouse T-SQL","notes":[],"refs":["R6"]},{"n":10,"batch":1,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1. Data is ingested into\nLakehouse1 as one flat table. The table contains the following columns.\n\nYou plan to load the data into a dimensional model and implement a star schema. From the original flat\ntable, you create two tables named FactSales and DimProduct. You will track changes in DimProduct.\nYou need to prepare the data.\nWhich three columns should you include in the DimProduct table? Each correct answer presents part of\nthe solution.\nNote: Each correct selection is worth one point.\n\nA. Date\nB. ProductName\nC. ProductColor\nD. TransactionID\nE. SalesAmount\nF. ProductID","options":[{"label":"A","text":"Date"},{"label":"B","text":"ProductName"},{"label":"C","text":"ProductColor"},{"label":"D","text":"TransactionID"},{"label":"E","text":"SalesAmount"},{"label":"F","text":"ProductID"}],"originalAnswer":"B, C, F","correctAnswer":"B, C, and F: ProductName, ProductColor, ProductID.","status":"Correct","explanation":"A product dimension contains the product business key and descriptive attributes. Date, TransactionID, and SalesAmount describe the sales event and belong in a date dimension or fact table.","conceptArea":"Ingest/transform – Dimensional modeling","notes":[],"refs":["R6"]},{"n":11,"batch":1,"question":"You have a Fabric workspace named Workspace1 that contains a notebook named Notebook1.\nIn Workspace1, you create a new notebook named Notebook2.\nYou need to ensure that you can attach Notebook2 to the same Apache Spark session as Notebook1.\nWhat should you do?\n\nA. Enable high concurrency for notebooks.\nB. Enable dynamic allocation for the Spark pool.\nC. Change the runtime version.\nD. Increase the number of executors.","options":[{"label":"A","text":"Enable high concurrency for notebooks."},{"label":"B","text":"Enable dynamic allocation for the Spark pool."},{"label":"C","text":"Change the runtime version."},{"label":"D","text":"Increase the number of executors."}],"originalAnswer":"A","correctAnswer":"A. Enable high concurrency for notebooks.","status":"Correct","explanation":"High concurrency enables supported notebooks to attach to the same Spark session and share session resources.","conceptArea":"Implement/manage – Spark compute","notes":[],"refs":["R2"]},{"n":12,"batch":1,"question":"You have a Fabric workspace named Workspace1 that contains a lakehouse named Lakehouse1.\nLakehouse1 contains the following tables:\nOrders\nCustomer\nEmployee\nThe Employee table contains Personally Identifiable Information (PII).\nA data engineer is building a workflow that requires writing data to the Customer table, however, the user\ndoes NOT have the elevated permissions required to view the contents of the Employee table.\nYou need to ensure that the data engineer can write data to the Customer table without reading data from\nthe Employee table.\nWhich three actions should you perform? Each correct answer presents part of the solution.\nNote: Each correct selection is worth one point.\n\nA. Share Lakehouse1 with the data engineer.\nB. Assign the data engineer the Contributor role for Workspace2.\nC. Assign the data engineer the Viewer role for Workspace2.\nD. Assign the data engineer the Contributor role for Workspace1.\nE. Migrate the Employee table from Lakehouse1 to Lakehouse2.\nF. Create a new workspace named Workspace2 that contains a new lakehouse named Lakehouse2.\nG. Assign the data engineer the Viewer role for Workspace1.","options":[{"label":"A","text":"Share Lakehouse1 with the data engineer."},{"label":"B","text":"Assign the data engineer the Contributor role for Workspace2."},{"label":"C","text":"Assign the data engineer the Viewer role for Workspace2."},{"label":"D","text":"Assign the data engineer the Contributor role for Workspace1."},{"label":"E","text":"Migrate the Employee table from Lakehouse1 to Lakehouse2."},{"label":"F","text":"Create a new workspace named Workspace2 that contains a new lakehouse named Lakehouse2."},{"label":"G","text":"Assign the data engineer the Viewer role for Workspace1."}],"originalAnswer":"D, E, F","correctAnswer":"D, E, and F: create Workspace2/Lakehouse2, move Employee there, and give the engineer Contributor in Workspace1.","status":"Correct","explanation":"Contributor is required for Spark writes to Customer, but that role would also expose Employee while it remains in the same workspace/lakehouse. Separating the PII table into another workspace preserves write access to Customer without giving access to Employee.","conceptArea":"Implement/manage – Workspace isolation","notes":[],"refs":["R3"]},{"n":13,"batch":1,"question":"You have a Fabric warehouse named DW1. DW1 contains a table that stores sales data and is used by\nmultiple sales representatives.\nYou plan to implement row-level security (RLS).\nYou need to ensure that the sales representatives can see only their respective data.\nWhich warehouse object do you require to implement RLS?\n\nA. STORED PROCEDURE\nB. CONSTRAINT\nC. SCHEMA\nD. FUNCTION","options":[{"label":"A","text":"STORED PROCEDURE"},{"label":"B","text":"CONSTRAINT"},{"label":"C","text":"SCHEMA"},{"label":"D","text":"FUNCTION"}],"originalAnswer":"D","correctAnswer":"D. FUNCTION.","status":"Correct","explanation":"RLS predicates are implemented as inline table-valued functions and enforced through a security policy.","conceptArea":"Implement/manage – Security (RLS)","notes":[],"refs":["R7"]},{"n":14,"batch":1,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace named Workspace1_DEV that contains the following items:\n10 reports\nFour notebooks\nThree lakehouses\nTwo data pipelines\nTwo Dataflow Gen1 dataflows\nThree Dataflow Gen2 dataflows\nFive semantic models that each has a scheduled refresh policy\nYou create a deployment pipeline named Pipeline1 to move items from Workspace1_DEV to a new\nworkspace named Workspace1_TEST.\nYou deploy all the items from Workspace1_DEV to Workspace1_TEST.\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"No; Yes; No","correctAnswer":"No; Yes; No.","status":"Correct","explanation":"Deployment pipelines deploy item definitions, not cached semantic-model data. Supported Dataflow Gen1 items deploy, while semantic-model refresh schedules are not copied to the target stage.","conceptArea":"Implement/manage – Deployment pipelines","notes":[],"refs":["R8","R9"]},{"n":15,"batch":1,"question":"You have a Fabric deployment pipeline that uses three workspaces named Dev, Test, and Prod.\nYou need to deploy an eventhouse as part of the deployment process.\nWhat should you use to add the eventhouse to the deployment process?\n\nA. GitHub Actions\nB. a deployment pipeline\nC. an Azure DevOps pipeline","options":[{"label":"A","text":"GitHub Actions"},{"label":"B","text":"a deployment pipeline"},{"label":"C","text":"an Azure DevOps pipeline"}],"originalAnswer":"C","correctAnswer":"B. A Fabric deployment pipeline.","status":"Wrong","explanation":"Eventhouse is now a supported deployment-pipeline item. The supplied Azure DevOps answer reflects an older product limitation and adds unnecessary external orchestration.","conceptArea":"Implement/manage – Deployment pipelines","notes":["Outdated: Eventhouse support has changed since the supplied answer was authored."],"refs":["R8"]},{"n":16,"batch":1,"question":"You have a Fabric workspace named Workspace1 that contains a warehouse named Warehouse1.\nYou plan to deploy Warehouse1 to a new workspace named Workspace2.\n\nAs part of the deployment process, you need to verify whether Warehouse1 contains invalid references.\nThe solution must minimize development effort.\nWhat should you use?\n\nA. a database project\nB. a deployment pipeline\nC. a Python script\nD. a T-SQL script","options":[{"label":"A","text":"a database project"},{"label":"B","text":"a deployment pipeline"},{"label":"C","text":"a Python script"},{"label":"D","text":"a T-SQL script"}],"originalAnswer":"B","correctAnswer":"A. A database project.","status":"Wrong","explanation":"Building a SQL database project validates object references and reports detailed build errors. A deployment pipeline moves supported Fabric items but is not the least-effort reference validator described by the question.","conceptArea":"Implement/manage – Warehouse CI/CD","notes":[],"refs":["R10"]},{"n":17,"batch":1,"question":"You have a Fabric workspace that contains a Real-Time Intelligence solution and an eventhouse.\nUsers report that from OneLake file explorer, they cannot see the data from the eventhouse.\nYou enable OneLake availability for the eventhouse.\nWhat will be copied to OneLake?\n\nA. only data added to new databases that are added to the eventhouse\nB. only the existing data in the eventhouse\nC. no data\nD. both new data and existing data in the eventhouse\nE. only new data added to the eventhouse","options":[{"label":"A","text":"only data added to new databases that are added to the eventhouse"},{"label":"B","text":"only the existing data in the eventhouse"},{"label":"C","text":"no data"},{"label":"D","text":"both new data and existing data in the eventhouse"},{"label":"E","text":"only new data added to the eventhouse"}],"originalAnswer":"E","correctAnswer":"E, if historic backfill is not selected: only newly added data is exposed.","status":"Correct","explanation":"Current OneLake availability supports an Apply to existing tables option. Without historic backfill, newly available data/tables are exposed; selecting that option makes existing and new data available, which would make D correct instead.","conceptArea":"Implement/manage – Eventhouse/OneLake","notes":["Ambiguous under the current UI because the question omits the Apply to existing tables choice."],"refs":["R11"]},{"n":18,"batch":1,"question":"You have a Fabric workspace named Workspace1.\nYou plan to integrate Workspace1 with Azure DevOps.\nYou will use a Fabric deployment pipeline named deployPipeline1 to deploy items from Workspace1 to\nhigher environment workspaces as part of a medallion architecture. You will run deployPipeline1 by using\nan API call from an Azure DevOps pipeline.\nYou need to configure API authentication between Azure DevOps and Fabric.\nWhich type of authentication should you use?\n\nA. service principal\nB. Microsoft Entra username and password\nC. managed private endpoint\nD. workspace identity","options":[{"label":"A","text":"service principal"},{"label":"B","text":"Microsoft Entra username and password"},{"label":"C","text":"managed private endpoint"},{"label":"D","text":"workspace identity"}],"originalAnswer":"A","correctAnswer":"A. Service principal.","status":"Correct","explanation":"A service principal is the appropriate non-interactive identity for an Azure DevOps pipeline calling Fabric deployment APIs; username/password and private endpoints are not API authentication mechanisms.","conceptArea":"Implement/manage – Automation identity","notes":[],"refs":["R8"]},{"n":19,"batch":1,"question":"You have a Google Cloud Storage (GCS) container named storage1 that contains the files shown in the\nfollowing table.\n\nYou have a Fabric workspace named Workspace1 that has the cache for shortcuts enabled. Workspace1\ncontains a lakehouse named Lakehouse1. Lakehouse1 has the shortcuts shown in the following table.\n\nYou need to read data from all the shortcuts.\nWhich shortcuts will retrieve data from the cache?\n\nA. Stores only\nB. Products only\nC. Stores and Products only\nD. Products, Stores, and Trips\nE. Trips only\nF. Products and Trips only\n\nExhibit: ProductFile.parquet 8 MB (last accessed 12 hours ago); StoreFile.json 500 MB (4 hours); TripsFile.csv 99 MB (48 hours).","options":[{"label":"A","text":"Stores only"},{"label":"B","text":"Products only"},{"label":"C","text":"Stores and Products only"},{"label":"D","text":"Products, Stores, and Trips"},{"label":"E","text":"Trips only"},{"label":"F","text":"Products and Trips only\n\nExhibit: ProductFile.parquet 8 MB (last accessed 12 hours ago); StoreFile.json 500 MB (4 hours); TripsFile.csv 99 MB (48 hours)."}],"originalAnswer":"C","correctAnswer":"C. Stores and Products only.","status":"Correct","explanation":"With the question's implied default one-day cache retention, the files last accessed 4 and 12 hours ago are cached, while the file last accessed 48 hours ago is not. All three files are below the 1-GB cacheability limit here.","conceptArea":"Implement/manage – OneLake shortcut cache","notes":["Ambiguous if the workspace cache retention was customized; current retention is configurable."],"refs":["R12"]},{"n":20,"batch":1,"question":"You have a Fabric workspace named Workspace1 that contains an Apache Spark job definition named\nJob1.\nYou have an Azure SQL database named Source1 that has public internet access disabled.\nYou need to ensure that Job1 can access the data in Source1.\nWhat should you create?\n\nA. an on-premises data gateway\nB. a managed private endpoint\nC. an integration runtime\nD. a data management gateway","options":[{"label":"A","text":"an on-premises data gateway"},{"label":"B","text":"a managed private endpoint"},{"label":"C","text":"an integration runtime"},{"label":"D","text":"a data management gateway"}],"originalAnswer":"B","correctAnswer":"B. A managed private endpoint.","status":"Correct","explanation":"A managed private endpoint provides private connectivity from Fabric Spark workloads to an Azure SQL database whose public endpoint is disabled.","conceptArea":"Implement/manage – Private connectivity","notes":[],"refs":["R13"]},{"n":21,"batch":1,"question":"You have an Azure Data Lake Storage Gen2 account named storage1 and an Amazon S3 bucket named\nstorage2.\nYou have the Delta Parquet files shown in the following table.\n\nYou have a Fabric workspace named Workspace1 that has the cache for shortcuts enabled. Workspace1\ncontains a lakehouse named Lakehouse1. Lakehouse1 has the following shortcuts:\nA shortcut to ProductFile aliased as Products\nA shortcut to StoreFile aliased as Stores\nA shortcut to TripsFile aliased as Trips\nThe data from which shortcuts will be retrieved from the cache?\n\nA. Trips and Stores only\nB. Products and Store only\nC. Stores only\nD. Products only\nE. Products, Stores, and Trips\n\nExhibit: Products is an ADLS Gen2 50-MB file; Stores is an S3 25-MB file; Trips is an S3 2-GB file.","options":[{"label":"A","text":"Trips and Stores only"},{"label":"B","text":"Products and Store only"},{"label":"C","text":"Stores only"},{"label":"D","text":"Products only"},{"label":"E","text":"Products, Stores, and Trips\n\nExhibit: Products is an ADLS Gen2 50-MB file; Stores is an S3 25-MB file; Trips is an S3 2-GB file."}],"originalAnswer":"B","correctAnswer":"C. Stores only.","status":"Wrong","explanation":"Shortcut cache supports the S3 shortcut for StoreFile and it is under the 1-GB per-file cache limit. The ADLS Gen2 shortcut is not covered by shortcut cache, and the 2-GB Trips file is too large to cache.","conceptArea":"Implement/manage – OneLake shortcut cache","notes":[],"refs":["R12"]},{"n":22,"batch":1,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace named Workspace1 that contains the items shown in the following table.\n\nFor Model1, the Keep your Direct Lake data up to date option is disabled.\nYou need to configure the execution of the items to meet the following requirements:\nNotebook1 must execute every weekday at 8:00 AM.\nNotebook2 must execute when a file is saved to an Azure Blob Storage container.\nModel1 must refresh when Notebook1 has executed successfully.\nHow should you orchestrate each item? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Notebook1→Pipeline1; Notebook2→Real-Time hub; schedule Pipeline1; Model1→Pipeline1","correctAnswer":"Notebook1: add to Pipeline1; Notebook2: configure from Real-Time hub; Pipeline1: schedule it; Model1: add a semantic-model refresh activity to Pipeline1.","status":"Correct","explanation":"A scheduled pipeline handles Notebook1 and the dependent model refresh. A Real-Time hub/Activator rule can react to a Blob event and run Notebook2 as a Fabric item.","conceptArea":"Implement/manage – Orchestration and events","notes":[],"refs":["R14","R28","R48"]},{"n":23,"batch":1,"question":"Your company has a sales department that uses two Fabric workspaces named Workspace1 and\nWorkspace2.\n\nThe company decides to implement a domain strategy to organize the workspaces.\nYou need to ensure that a user can perform the following tasks:\nCreate a new domain for the sales department.\nCreate two subdomains: one for the east region and one for the west region.\nAssign Workspace1 to the east region subdomain.\nAssign Workspace2 to the west region subdomain.\nThe solution must follow the principle of least privilege.\nWhich role should you assign to the user?\n\nA. workspace Admin\nB. domain admin\nC. domain contributor\nD. Fabric admin","options":[{"label":"A","text":"workspace Admin"},{"label":"B","text":"domain admin"},{"label":"C","text":"domain contributor"},{"label":"D","text":"Fabric admin"}],"originalAnswer":"D","correctAnswer":"D. Fabric admin.","status":"Correct","explanation":"Only a Fabric admin can create a top-level domain. A domain admin can manage an existing domain, create subdomains, and assign workspaces, but cannot satisfy the first requirement.","conceptArea":"Implement/manage – Domains","notes":[],"refs":["R15"]},{"n":24,"batch":1,"question":"You have a Fabric workspace named Workspace1 that contains a warehouse named DW1 and a data\npipeline named Pipeline1.\nYou plan to add a user named User3 to Workspace1.\nYou need to ensure that User3 can perform the following actions:\nView all the items in Workspace1.\nUpdate the tables in DW1.\nThe solution must follow the principle of least privilege.\nYou already assigned the appropriate object-level permissions to DW1.\nWhich workspace role should you assign to User3?\n\nA. Admin\nB. Member\nC. Viewer\nD. Contributor","options":[{"label":"A","text":"Admin"},{"label":"B","text":"Member"},{"label":"C","text":"Viewer"},{"label":"D","text":"Contributor"}],"originalAnswer":"D","correctAnswer":"C. Viewer.","status":"Wrong","explanation":"The existing SQL object-level grants authorize the UPDATE operation in DW1. Viewer is the least-privilege workspace role that lets User3 discover/connect to the item; Contributor would grant unnecessary item creation and modification rights.","conceptArea":"Implement/manage – Workspace and SQL permissions","notes":[],"refs":["R16"]},{"n":25,"batch":1,"question":"You have a Fabric capacity that contains a workspace named Workspace1. Workspace1 contains a\nlakehouse named Lakehouse1, a data pipeline, a notebook, and several Microsoft Power BI reports.\nA user named User1 wants to use SQL to analyze the data in Lakehouse1.\nYou need to configure access for User1. The solution must meet the following requirements:\nProvide User1 with read access to the table data in Lakehouse1.\nPrevent User1 from using Apache Spark to query the underlying files in Lakehouse1.\nPrevent User1 from accessing other items in Workspace1.\nWhat should you do?\n\nA. Share Lakehouse1 with User1 directly and select Read all SQL endpoint data.\nB. Assign User1 the Viewer role for Workspace1. Share Lakehouse1 with User1 and select Read all SQL\nendpoint data.\nC. Share Lakehouse1 with User1 directly and select Build reports on the default semantic model.\nD. Assign User1 the Member role for Workspace1. Share Lakehouse1 with User1 and select Read all\nSQL endpoint data.","options":[{"label":"A","text":"Share Lakehouse1 with User1 directly and select Read all SQL endpoint data."},{"label":"B","text":"Assign User1 the Viewer role for Workspace1. Share Lakehouse1 with User1 and select Read all SQL\nendpoint data."},{"label":"C","text":"Share Lakehouse1 with User1 directly and select Build reports on the default semantic model."},{"label":"D","text":"Assign User1 the Member role for Workspace1. Share Lakehouse1 with User1 and select Read all\nSQL endpoint data."}],"originalAnswer":"A","correctAnswer":"A. Share Lakehouse1 directly and grant Read all SQL endpoint data.","status":"Correct","explanation":"Direct item sharing avoids access to other workspace items. Granting SQL endpoint read data but not Spark read access meets the table-only requirement.","conceptArea":"Implement/manage – Lakehouse security","notes":[],"refs":["R3"]},{"n":26,"batch":2,"question":"DRAG DROP (Drag and Drop is not supported)\nYou are implementing the following data entities in a Fabric environment:\n1. Entity1: Available in a lakehouse and contains data that will be used as a core organization entity\n2. Entity2: Available in a semantic model and contains data that meets organizational standards\n3. Entity3: Available in a Microsoft Power BI report and contains data that is ready for sharing and reuse\n4. Entity4: Available in a Power BI dashboard and contains approved data for executive-level decision\nmaking\nYour company requires that specific governance processes be implemented for the data.\nYou need to apply endorsement badges to the entities based on each entity's use case.\nWhich badge should you apply to each entity? To answer, drag the appropriate badges the correct\nentities. Each badge may be used once, more than once, or not at all. You may need to drag the split bar\nbetween panes or scroll to view content.\nNote: Each correct selection is worth one point.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Entity1 Master data; Entity2 Certified; Entity3 Promoted; Entity4 Certified","correctAnswer":"Entity1: Master data; Entity2: Certified; Entity3: Promoted; Entity4: Cannot be endorsed.","status":"Wrong","explanation":"Master data applies to an authoritative core data item, Certified to validated semantic data, and Promoted to content ready for broader reuse. Power BI dashboards do not support endorsement, so Entity4 cannot be Certified despite its business importance.","conceptArea":"Implement/manage – Governance and endorsement","notes":[],"refs":["R17"]},{"n":27,"batch":2,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have three users named User1, User2, and User3.\nYou have the Fabric workspaces shown in the following table.\n\nYou have a security group named Group1 that contains User1 and User3.\nThe Fabric admin creates the domains shown in the following table.\n\nUser1 creates a new workspace named Workspace3.\nYou add Group1 to the default domain of Domain1.\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\n\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nExhibit facts/statements: Workspace1 admin User1; Workspace2 admin User2; Domain1 admin User1; Domain2 admin User2. Evaluate: User3 Viewer in Workspace3; User3 Domain contributor in Domain1; User2 Contributor in Workspace3.","options":[{"label":"A","text":"See Explanation section for answer.\n\nExhibit facts/statements: Workspace1 admin User1; Workspace2 admin User2; Domain1 admin User1; Domain2 admin User2. Evaluate: User3 Viewer in Workspace3; User3 Domain contributor in Domain1; User2 Contributor in Workspace3."}],"originalAnswer":"Yes; No; No","correctAnswer":"No; Yes; No.","status":"Wrong","explanation":"Adding Group1 as default-domain users does not give User3 Viewer access to Workspace3. It does make group members domain contributors, while User2 receives no automatic Contributor role in the new workspace.","conceptArea":"Implement/manage – Domains","notes":[],"refs":["R15"]},{"n":28,"batch":2,"question":"You have two Fabric workspaces named Workspace1 and Workspace2.\nYou have a Fabric deployment pipeline named deployPipeline1 that deploys items from Workspace1 to\nWorkspace2. DeployPipeline1 contains all the items in Workspace1.\nYou recently modified the items in Workspaces1.\nThe workspaces currently contain the items shown in the following table.\n\nItems in Workspace1 that have the same name as items in Workspace2 are currently paired.\nYou need to ensure that the items in Workspace1 overwrite the corresponding items in Workspace2. The\nsolution must minimize effort.\nWhat should you do?\n\nA. Delete all the items in Workspace2, and then run deployPipeline1.\nB. Rename each item in Workspace2 to have the same name as the items in Workspace1.\nC. Back up the items in Workspace2, and then run deployPipeline1.\nD. Run deployPipeline1 without modifying the items in Workspace2.","options":[{"label":"A","text":"Delete all the items in Workspace2, and then run deployPipeline1."},{"label":"B","text":"Rename each item in Workspace2 to have the same name as the items in Workspace1."},{"label":"C","text":"Back up the items in Workspace2, and then run deployPipeline1."},{"label":"D","text":"Run deployPipeline1 without modifying the items in Workspace2."}],"originalAnswer":"D","correctAnswer":"D. Run deployPipeline1 without modifying Workspace2.","status":"Correct","explanation":"Paired items retain their identity across stages; deploying updates overwrites the paired target item definition. No delete, rename, or manual backup is required by the stated goal.","conceptArea":"Implement/manage – Deployment pipelines","notes":[],"refs":["R9"]},{"n":29,"batch":2,"question":"You have a Fabric workspace named Workspace1 that contains a data pipeline named Pipeline1 and a\nlakehouse named Lakehouse1.\nYou have a deployment pipeline named deployPipeline1 that deploys Workspace1 to Workspace2.\nYou restructure Workspace1 by adding a folder named Folder1 and moving Pipeline1 to Folder1.\nYou use deployPipeline1 to deploy Workspace1 to Workspace2.\nWhat occurs to Workspace2?\n\nA. Folder1 is created, Pipeline1 moves to Folder1, and Lakehouse1 is deployed.\nB. Only Pipeline1 and Lakehouse1 are deployed.\nC. Folder1 is created, and Pipeline1 and Lakehouse1 move to Folder1.\nD. Only Folder1 is created and Pipeline1 moves to Folder1.","options":[{"label":"A","text":"Folder1 is created, Pipeline1 moves to Folder1, and Lakehouse1 is deployed."},{"label":"B","text":"Only Pipeline1 and Lakehouse1 are deployed."},{"label":"C","text":"Folder1 is created, and Pipeline1 and Lakehouse1 move to Folder1."},{"label":"D","text":"Only Folder1 is created and Pipeline1 moves to Folder1."}],"originalAnswer":"A","correctAnswer":"A. Folder1 is created, Pipeline1 moves to it, and Lakehouse1 is deployed.","status":"Correct","explanation":"Current deployment pipelines preserve supported workspace folder hierarchy and deploy the other supported items in the stage.","conceptArea":"Implement/manage – Deployment pipelines","notes":[],"refs":["R9"]},{"n":30,"batch":2,"question":"DRAG DROP (Drag and Drop is not supported)\nYour company has a team of developers. The team creates Python libraries of reusable code that is used\nto transform data.\nYou create a Fabric workspace name Workspace1 that will be used to develop extract, transform, and\nload (ETL) solutions by using notebooks.\nYou need to ensure that the libraries are available by default to new notebooks in Workspace1.\nWhich three actions should you perform in sequence? To answer, move the appropriate actions from the\nlist of actions to the answer area and arrange them in the correct order.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Create Environment → install libraries → set default Environment","correctAnswer":"1) Create an Environment; 2) install the Python libraries in it; 3) set it as the workspace default environment.","status":"Correct","explanation":"An Environment centralizes library dependencies. Making it the workspace default causes new notebooks to inherit those libraries without per-notebook installation.","conceptArea":"Implement/manage – Spark environments","notes":[],"refs":["R18"]},{"n":31,"batch":2,"question":"You have a Fabric workspace that contains a lakehouse and a notebook named Notebook1. Notebook1\nreads data into a DataFrame from a table named Table1 and applies transformation logic. The data from\nthe DataFrame is then written to a new Delta table named Table2 by using a merge operation.\nYou need to consolidate the underlying Parquet files in Table1.\nWhich command should you run?\n\nA. VACUUM\nB. BROADCAST\nC. OPTIMIZE\nD. CACHE","options":[{"label":"A","text":"VACUUM"},{"label":"B","text":"BROADCAST"},{"label":"C","text":"OPTIMIZE"},{"label":"D","text":"CACHE"}],"originalAnswer":"C","correctAnswer":"C. OPTIMIZE.","status":"Correct","explanation":"OPTIMIZE compacts many small Parquet files underlying a Delta table into fewer larger files. VACUUM removes obsolete unreferenced files instead of compacting active files.","conceptArea":"Monitor/optimize – Delta maintenance","notes":[],"refs":["R19"]},{"n":32,"batch":2,"question":"You have five Fabric workspaces.\nYou are monitoring the execution of items by using Monitoring hub.\nYou need to identify in which workspace a specific item runs.\nWhich column should you view in Monitoring hub?\n\nA. Start time\nB. Capacity\nC. Activity name\nD. Submitter\nE. Item type\nF. Job type\nG. Location","options":[{"label":"A","text":"Start time"},{"label":"B","text":"Capacity"},{"label":"C","text":"Activity name"},{"label":"D","text":"Submitter"},{"label":"E","text":"Item type"},{"label":"F","text":"Job type"},{"label":"G","text":"Location"}],"originalAnswer":"G","correctAnswer":"G. Location.","status":"Correct","explanation":"The Monitoring hub Location column identifies the workspace in which the monitored item/job runs.","conceptArea":"Monitor/optimize – Monitoring hub","notes":[],"refs":["R20"]},{"n":33,"batch":2,"question":"You have a Fabric workspace that contains a warehouse named DW1. DW1 is loaded by using a\nnotebook named Notebook1.\nYou need to identify which version of Delta was used when Notebook1 was executed.\nWhat should you use?\n\nA. Real-Time hub\nB. OneLake data hub\nC. the Admin monitoring workspace\nD. Fabric Monitor\nE. the Microsoft Fabric Capacity Metrics app","options":[{"label":"A","text":"Real-Time hub"},{"label":"B","text":"OneLake data hub"},{"label":"C","text":"the Admin monitoring workspace"},{"label":"D","text":"Fabric Monitor"},{"label":"E","text":"the Microsoft Fabric Capacity Metrics app"}],"originalAnswer":"D","correctAnswer":"D. Fabric Monitor.","status":"Correct","explanation":"The Spark application details reached from Fabric monitoring expose runtime/application properties needed to identify the Delta runtime used by the notebook. Capacity Metrics and Real-Time hub do not expose that execution detail.","conceptArea":"Monitor/optimize – Spark monitoring","notes":[],"refs":["R20","R41"]},{"n":34,"batch":2,"question":"DRAG DROP (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a warehouse named Warehouse1.\nIn Warehouse1, you create a table named DimCustomer by running the following statement.\n\nYou need to set the Customerkey column as a primary key of the DimCustomer table.\nWhich three code segments should you run in sequence? To answer, move the appropriate code\nsegments from the list of code segments to the answer area and arrange them in the correct order.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"ALTER TABLE → PRIMARY KEY CLUSTERED → ENFORCED","correctAnswer":"ALTER TABLE dbo.DimCustomer; ADD CONSTRAINT PK_DimCustomer PRIMARY KEY NONCLUSTERED (CustomerKey); NOT ENFORCED.","status":"Wrong","explanation":"Fabric Warehouse supports a primary key only as NONCLUSTERED and NOT ENFORCED. The supplied CLUSTERED/ENFORCED sequence is unsupported and incorrectly implies physical enforcement.","conceptArea":"Implement/manage – Warehouse constraints","notes":[],"refs":["R21"]},{"n":35,"batch":2,"question":"You have a Fabric workspace that contains a semantic model named Model1.\nYou need to dynamically execute and monitor the refresh progress of Model1.\nWhat should you use?\n\nA. dynamic management views in Microsoft SQL Server Management Studio (SSMS)\nB. Monitoring hub\nC. dynamic management views in Azure Data Studio\nD. a semantic link in a notebook","options":[{"label":"A","text":"dynamic management views in Microsoft SQL Server Management Studio (SSMS)"},{"label":"B","text":"Monitoring hub"},{"label":"C","text":"dynamic management views in Azure Data Studio"},{"label":"D","text":"a semantic link in a notebook"}],"originalAnswer":"D","correctAnswer":"D. Semantic Link in a notebook.","status":"Correct","explanation":"Semantic Link/SemPy can programmatically start semantic-model operations and inspect refresh status from a notebook. Monitoring hub alone does not provide the requested dynamic execution API.","conceptArea":"Monitor/optimize – Semantic models","notes":[],"refs":["R22"]},{"n":36,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a Fabric eventstream that loads data into a table named Bike_Location in a KQL database. The\ntable contains the following columns:\nBikepointID\nStreet\nNeighbourhood\nNo_Bikes\nNo_Empty_Docks\nTimestamp\nYou need to apply transformation and filter logic to prepare the data for consumption. The solution must\nreturn data for a neighbourhood named Sands End when No_Bikes is at least 15. The results must be\nordered by No_Bikes in ascending order.\nSolution: You use the following code segment:\n\nDoes this meet the goal?\n\nA. Yes\nB. No\n\nCode exhibit: `Bike_Location | filter Neighbourhood == \"Sands End\" and No_Bikes >= 15 | sort by No_Bikes | project ...`.","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No\n\nCode exhibit: `Bike_Location | filter Neighbourhood == \"Sands End\" and No_Bikes >= 15 | sort by No_Bikes | project ...`."}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"KQL sort/order is descending by default. The filter is correct, but `sort by No_Bikes` without `asc` does not meet the ascending-order requirement. The supplied rationale incorrectly said the default is ascending.","conceptArea":"Ingest/transform – KQL","notes":[],"refs":["R23"]},{"n":37,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\n\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a Fabric eventstream that loads data into a table named Bike_Location in a KQL database. The\ntable contains the following columns:\nBikepointID\nStreet\nNeighbourhood\nNo_Bikes\nNo_Empty_Docks\nTimestamp\nYou need to apply transformation and filter logic to prepare the data for consumption. The solution must\nreturn data for a neighbourhood named Sands End when No_Bikes is at least 15. The results must be\nordered by No_Bikes in ascending order.\nSolution: You use the following code segment:\n\nDoes this meet the goal?\n\nA. Yes\nB. No\n\nCode exhibit: `Bike_Location | filter ... | order by No_Bikes | project ...`.","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No\n\nCode exhibit: `Bike_Location | filter ... | order by No_Bikes | project ...`."}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"`order by` is a valid KQL alias for `sort by`; the problem is not the operator name. Because the code omits `asc`, it sorts descending by default and fails the goal.","conceptArea":"Ingest/transform – KQL","notes":[],"refs":["R23"]},{"n":38,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a Fabric eventstream that loads data into a table named Bike_Location in a KQL database. The\ntable contains the following columns:\nBikepointID\nStreet\nNeighbourhood\nNo_Bikes\nNo_Empty_Docks\nTimestamp\nYou need to apply transformation and filter logic to prepare the data for consumption. The solution must\nreturn data for a neighbourhood named Sands End when No_Bikes is at least 15. The results must be\nordered by No_Bikes in ascending order.\n\nSolution: You use the following code segment:\n\nDoes this meet the goal?\n\nA. Yes\nB. No\n\nCode exhibit: `Bike_Location | filter ... | sort by No_Bikes asc | project ...`.","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No\n\nCode exhibit: `Bike_Location | filter ... | sort by No_Bikes asc | project ...`."}],"originalAnswer":"A","correctAnswer":"A. Yes.","status":"Correct","explanation":"The code filters Sands End with No_Bikes >= 15 and explicitly sorts No_Bikes ascending before projection.","conceptArea":"Ingest/transform – KQL","notes":[],"refs":["R23"]},{"n":39,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a Fabric eventstream that loads data into a table named Bike_Location in a KQL database. The\ntable contains the following columns:\nBikepointID\nStreet\nNeighbourhood\nNo_Bikes\nNo_Empty_Docks\nTimestamp\nYou need to apply transformation and filter logic to prepare the data for consumption. The solution must\nreturn data for a neighbourhood named Sands End when No_Bikes is at least 15. The results must be\nordered by No_Bikes in ascending order.\nSolution: You use the following code segment:\n\nDoes this meet the goal?\n\nA. Yes\nB. No\n\nCode exhibit: SQL SELECT ... FROM bike_location WHERE neighbourhood='Sands End' AND no_bikes>=15 ORDER BY no_bikes.","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No\n\nCode exhibit: SQL SELECT ... FROM bike_location WHERE neighbourhood='Sands End' AND no_bikes>=15 ORDER BY no_bikes."}],"originalAnswer":"A","correctAnswer":"A. Yes.","status":"Correct","explanation":"The SQL query filters the required rows and `ORDER BY no_bikes` is ascending by default in T-SQL, so it meets the stated goal.","conceptArea":"Ingest/transform – T-SQL","notes":[],"refs":["R6"]},{"n":40,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\n\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have an Azure key vault named KeyVault1 that contains secrets.\nYou have a Fabric workspace named Workspace1. Workspace contains a notebook named Notebook1\nthat performs the following tasks:\nLoads stage data to the target tables in a lakehouse\nTriggers the refresh of a semantic model\nYou plan to add functionality to Notebook1 that will use the Fabric API to monitor the semantic model\nrefreshes.\nYou need to retrieve the registered application ID and secret from KeyVault1 to generate the\nauthentication token.\nSolution: You use the following code segment:\nUse notebookutils.credentials.getSecret and specify the key vault URL and key vault secret.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"A","correctAnswer":"A. Yes.","status":"Correct","explanation":"`notebookutils.credentials.getSecret` is the retrieval method for a named secret in Azure Key Vault and can supply the application credential needed for token creation.","conceptArea":"Implement/manage – Secrets","notes":[],"refs":["R24"]},{"n":41,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have an Azure key vault named KeyVault1 that contains secrets.\nYou have a Fabric workspace named Workspace1. Workspace contains a notebook named Notebook1\nthat performs the following tasks:\nLoads stage data to the target tables in a lakehouse\nTriggers the refresh of a semantic model\nYou plan to add functionality to Notebook1 that will use the Fabric API to monitor the semantic model\nrefreshes.\nYou need to retrieve the registered application ID and secret from KeyVault1 to generate the\nauthentication token.\n\nSolution: You use the following code segment:\nUse notebookutils.credentials.putSecret and specify the key vault URL and key vault secret.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"`putSecret` writes or updates a secret; it does not retrieve the application ID or secret required by the notebook.","conceptArea":"Implement/manage – Secrets","notes":[],"refs":["R24"]},{"n":42,"batch":2,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have an Azure key vault named KeyVault1 that contains secrets.\nYou have a Fabric workspace named Workspace1. Workspace contains a notebook named Notebook1\nthat performs the following tasks:\nLoads stage data to the target tables in a lakehouse\nTriggers the refresh of a semantic model\nYou plan to add functionality to Notebook1 that will use the Fabric API to monitor the semantic model\nrefreshes.\nYou need to retrieve the registered application ID and secret from KeyVault1 to generate the\nauthentication token.\nSolution: You use the following code segment:\nUse notebookutils.credentials.getSecret and specify the key vault URL and the name of a linked service.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"The retrieval call must identify the secret. Supplying only a vault URL and linked-service name omits the secret name and therefore cannot meet the requirement.","conceptArea":"Implement/manage – Secrets","notes":[],"refs":["R24"]},{"n":43,"batch":2,"question":"DRAG DROP (Drag and Drop is not supported)\nYou have two Fabric notebooks named Load_Salesperson and Load_Orders that read data from Parquet\nfiles in a lakehouse. Load_Salesperson writes to a Delta table named dim_salesperson. Load_Orders\nwrites to a Delta table named fact_orders and is dependent on the successful execution of\nLoad_Salesperson.\nYou need to implement a pattern to dynamically execute Load_Salesperson and Load_Orders in the\nappropriate order by using a notebook.\nHow should you complete the code? To answer, drag the appropriate values the correct targets. Each\nvalue may be used once, more than once, or not at all. You may need to drag the split bar between panes\nor scroll to view content.\nNote: Each correct selection is worth one point.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"activities; dependencies; runMultiple","correctAnswer":"Use `activities`, add `dependencies` from Load_Orders to Load_Salesperson, and call `runMultiple`.","status":"Correct","explanation":"The notebook DAG is defined by an activities array. The dependency produces the required topological order, and `notebookutils.notebook.runMultiple`/the compatible utility executes the DAG.","conceptArea":"Implement/manage – Notebook orchestration","notes":[],"refs":["R24"]},{"n":44,"batch":2,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace named Workspace1 that contains a warehouse named Warehouse2.\nA team of data analysts has Viewer role access to Workspace1.\nYou create a table by running the following statement.\n\nYou need to ensure that the team can view only the first two characters and the last four characters of the\nCreditCard attribute.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"ALTER TABLE; ALTER COLUMN; partial(2,\"XXXXXXXX\",4)","correctAnswer":"ALTER TABLE; ALTER COLUMN; masking function `partial(2,\"XXXXXXXX\",4)`.","status":"Correct","explanation":"Changing masking on an existing column uses ALTER TABLE ... ALTER COLUMN ... ADD MASKED. The partial function exposes the requested two-character prefix and four-character suffix with a custom middle padding string.","conceptArea":"Implement/manage – Dynamic data masking","notes":[],"refs":["R26"]},{"n":45,"batch":2,"question":"HOTSPOT (Drag and Drop is not supported)\nYou are building a data orchestration pattern by using a Fabric data pipeline named Dynamic Data Copy\nas shown in the exhibit. (Click the Exhibit tab.)\n\nDynamic Data Copy does NOT use parametrization.\nYou need to configure the ForEach activity to receive the list of tables to be copied.\nHow should you complete the pipeline expression? To answer, select the appropriate options in the\nanswer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"@activity('Lookup Schema and Table').output.value","correctAnswer":"`@activity('Lookup Schema and Table').output.value`.","status":"Correct","explanation":"A Lookup activity with First row only disabled returns its list in `output.value`; the ForEach Items property should iterate that array.","conceptArea":"Implement/manage – Pipeline expressions","notes":[],"refs":["R25"]},{"n":46,"batch":2,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a warehouse named Warehouse1. Warehouse1 contains a\ntable named DimCustomers. DimCustomers contains the following columns:\nCustomerName\nCustomerID\nBirthDate\nEmailAddress\nYou need to configure security to meet the following requirements:\nBirthDate in DimCustomer must be masked and display 1900-01-01.\nEmailAddress in DimCustomer must be masked and display only the first leading character and the last\nfive characters.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"random(1900-01-01,1900-01-01); partial(1,\"@\",5)","correctAnswer":"BirthDate: `default()`; EmailAddress: `partial(1,\"@\",5)`.","status":"Wrong","explanation":"For a date column, `default()` masks the value as 1900-01-01. `random` is for numeric types and is invalid for the date requirement; the partial email mask correctly exposes one leading and five trailing characters.","conceptArea":"Implement/manage – Dynamic data masking","notes":[],"refs":["R26"]},{"n":47,"batch":2,"question":"You have a Fabric workspace named Workspace1 that contains the following items:\nA Microsoft Power BI report named Report1\nA Power BI dashboard named Dashboard1\n\nA semantic model named Model1\nA lakehouse name Lakehouse1\nYour company requires that specific governance processes be implemented for the items.\nWhich items can you endorse in Fabric?\n\nA. Lakehouse1, Model1, and Dashboard1 only\nB. Lakehouse1, Model1, Report1 and Dashboard1\nC. Report1 and Dashboard1 only\nD. Model1, Report1, and Dashboard1 only\nE. Lakehouse1, Model1, and Report1 only","options":[{"label":"A","text":"Lakehouse1, Model1, and Dashboard1 only"},{"label":"B","text":"Lakehouse1, Model1, Report1 and Dashboard1"},{"label":"C","text":"Report1 and Dashboard1 only"},{"label":"D","text":"Model1, Report1, and Dashboard1 only"},{"label":"E","text":"Lakehouse1, Model1, and Report1 only"}],"originalAnswer":"E","correctAnswer":"E. Lakehouse1, Model1, and Report1 only.","status":"Correct","explanation":"Lakehouses, semantic models, and reports can be endorsed. Power BI dashboards do not support endorsement.","conceptArea":"Implement/manage – Governance and endorsement","notes":[],"refs":["R17"]},{"n":48,"batch":2,"question":"You have a Fabric workspace named Workspace1.\nYour company acquires GitHub licenses.\nYou need to configure source control for Workpace1 to use GitHub. The solution must follow the principle\nof least privilege.\nWhich permissions do you require to ensure that you can commit code to GitHub?\n\nA. Actions (Read and write) and Contents (Read and write)\nB. Actions (Read and write) only\nC. Contents (Read and write) only\nD. Contents (Read) and Commit statuses (Read and write)","options":[{"label":"A","text":"Actions (Read and write) and Contents (Read and write)"},{"label":"B","text":"Actions (Read and write) only"},{"label":"C","text":"Contents (Read and write) only"},{"label":"D","text":"Contents (Read) and Commit statuses (Read and write)"}],"originalAnswer":"C","correctAnswer":"C. GitHub Contents permission: Read and write.","status":"Correct","explanation":"Fabric needs repository content read/write access to commit and synchronize files. GitHub Actions permission is not required merely to commit workspace changes.","conceptArea":"Implement/manage – Git","notes":[],"refs":["R4"]},{"n":49,"batch":2,"question":"You have a Fabric workspace named Workspace1.\nYou plan to configure Git integration for Workspace1 by using an Azure DevOps Git repository.\nAn Azure DevOps admin creates the required artifacts to support the integration of Workspace1.\nWhich details do you require to perform the integration?\n\nA. the organization, project, Git repository, and branch\nB. the personal access token (PAT) for Git authentication and the Git repository URL\nC. the project, Git repository, branch, and Git folder\nD. the Git repository URL and the Git folder","options":[{"label":"A","text":"the organization, project, Git repository, and branch"},{"label":"B","text":"the personal access token (PAT) for Git authentication and the Git repository URL"},{"label":"C","text":"the project, Git repository, branch, and Git folder"},{"label":"D","text":"the Git repository URL and the Git folder"}],"originalAnswer":"A","correctAnswer":"A. Organization, project, Git repository, and branch.","status":"Correct","explanation":"Those Azure DevOps repository coordinates are required to connect the workspace. A Git folder can be selected but is optional, and a manually supplied PAT is not the normal Fabric workspace connection detail in this scenario.","conceptArea":"Implement/manage – Git","notes":[],"refs":["R4"]},{"n":50,"batch":2,"question":"You have a Fabric workspace that contains a lakehouse and a semantic model named Model1.\nYou use a notebook named Notebook1 to ingest and transform data from an external data source.\nYou need to execute Notebook1 as part of a data pipeline named Pipeline1. The process must meet the\nfollowing requirements:\nRun daily at 07:00 AM UTC.\nAttempt to retry Notebook1 twice if the notebook fails.\nAfter Notebook1 executes successfully, refresh Model1.\nWhich three actions should you perform? Each correct answer presents part of the solution.\nNote: Each correct selection is worth one point.\n\nA. Place the Semantic model refresh activity after the Notebook activity and link the activities by using the\nOn success condition.\nB. From the Schedule settings of Pipeline1, set the time zone to UTC.\nC. Set the Retry setting of the Notebook activity to 2.\nD. From the Schedule settings of Notebook1, set the time zone to UTC.\nE. Set the Retry setting of the Semantic model refresh activity to 2.\nF. Place the Semantic model refresh activity after the Notebook activity and link the activities by using an\nOn completion condition.","options":[{"label":"A","text":"Place the Semantic model refresh activity after the Notebook activity and link the activities by using the\nOn success condition."},{"label":"B","text":"From the Schedule settings of Pipeline1, set the time zone to UTC."},{"label":"C","text":"Set the Retry setting of the Notebook activity to 2."},{"label":"D","text":"From the Schedule settings of Notebook1, set the time zone to UTC."},{"label":"E","text":"Set the Retry setting of the Semantic model refresh activity to 2."},{"label":"F","text":"Place the Semantic model refresh activity after the Notebook activity and link the activities by using an\nOn completion condition."}],"originalAnswer":"A, B, C","correctAnswer":"A, B, and C.","status":"Correct","explanation":"Schedule Pipeline1 in UTC, set Notebook activity Retry to 2, and connect the semantic-model refresh activity with an On success dependency. On completion could refresh after a failed notebook, violating the requirement.","conceptArea":"Implement/manage – Pipeline orchestration","notes":[],"refs":["R28","R48"]},{"n":51,"batch":3,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1.\nYou plan to create a data pipeline named Pipeline1 to ingest data into Lakehouse1. You will use a\nparameter named param1 to pass an external value into Pipeline1. The param1 parameter has a data\ntype of int.\nYou need to ensure that the pipeline expression returns param1 as an int value.\nHow should you specify the parameter value?\n\nA. \"@pipeline().parameters.param1\"\nB. \"@{pipeline().parameters.param1}\"\nC. \"@{pipeline().parameters.[param1]}\"\nD. \"@@{pipeline().parameters.param1}\"","options":[{"label":"A","text":"\"@pipeline().parameters.param1\""},{"label":"B","text":"\"@{pipeline().parameters.param1}\""},{"label":"C","text":"\"@{pipeline().parameters.[param1]}\""},{"label":"D","text":"\"@@{pipeline().parameters.param1}\""}],"originalAnswer":"B","correctAnswer":"A. `@pipeline().parameters.param1`.","status":"Wrong","explanation":"A bare expression preserves the parameter's integer type. String interpolation using `@{...}` always produces a string, so the supplied B answer violates the explicit int requirement.","conceptArea":"Implement/manage – Pipeline expressions","notes":[],"refs":["R25"]},{"n":52,"batch":3,"question":"You have a Fabric workspace named Workspace1 that contains a lakehouse named Lakehouse1.\nWorkspace1 contains the following items:\nA Dataflow Gen2 dataflow that copies data from an on-premises Microsoft SQL Server database to\nLakehouse1\nA notebook that transforms files and loads the data to Lakehouse1\nA data pipeline that loads a CSV file to Lakehouse1\nYou need to develop an orchestration solution in Fabric that will load each item one after the other. The\nsolution must be scheduled to run every 15 minutes.\nWhich type of item should you use?\n\nA. notebook\nB. warehouse\nC. Dataflow Gen2 dataflow\nD. data pipeline","options":[{"label":"A","text":"notebook"},{"label":"B","text":"warehouse"},{"label":"C","text":"Dataflow Gen2 dataflow"},{"label":"D","text":"data pipeline"}],"originalAnswer":"D","correctAnswer":"D. A data pipeline.","status":"Correct","explanation":"A data pipeline can sequence Dataflow, notebook, and copy activities and can be scheduled every 15 minutes.","conceptArea":"Implement/manage – Pipeline orchestration","notes":[],"refs":["R28"]},{"n":53,"batch":3,"question":"You are building a Fabric notebook named MasterNotebook1 in a workspace. MasterNotebook1 contains\nthe following code.\n\nYou need to ensure that the notebooks are executed in the following sequence:\n1. Notebook_03\n2. Notebook_01\n3. Notebook_02\nWhich two actions should you perform? Each correct answer presents part of the solution.\nNote: Each correct selection is worth one point.\n\nA. Move the declaration of Notebook_02 to the bottom of the Directed Acyclic Graph (DAG) definition.\nB. Add dependencies to the execution of Notebook_03.\nC. Split the Directed Acyclic Graph (DAG) definition into three separate definitions.\nD. Add dependencies to the execution of Notebook_02.\nE. Change the concurrency to 3.\nF. Move the declaration of Notebook_03 to the top of the Directed Acyclic Graph (DAG) definition.\n\nCode exhibit: runMultiple DAG lists Notebook_01, Notebook_02, and Notebook_03 without dependencies and with concurrency 0; declaration order alone is not a dependency chain.","options":[{"label":"A","text":"Move the declaration of Notebook_02 to the bottom of the Directed Acyclic Graph (DAG) definition."},{"label":"B","text":"Add dependencies to the execution of Notebook_03."},{"label":"C","text":"Split the Directed Acyclic Graph (DAG) definition into three separate definitions."},{"label":"D","text":"Add dependencies to the execution of Notebook_02."},{"label":"E","text":"Change the concurrency to 3."},{"label":"F","text":"Move the declaration of Notebook_03 to the top of the Directed Acyclic Graph (DAG) definition.\n\nCode exhibit: runMultiple DAG lists Notebook_01, Notebook_02, and Notebook_03 without dependencies and with concurrency 0; declaration order alone is not a dependency chain."}],"originalAnswer":"D, F","correctAnswer":"No listed pair is sufficient. Set Notebook_01 dependencies to Notebook_03 and Notebook_02 dependencies to Notebook_01.","status":"Wrong","explanation":"DAG declaration order does not establish execution order for activities without dependencies. Moving Notebook_03 to the top and adding only Notebook_02 dependencies cannot guarantee 03 → 01 → 02; the question omits the required action for Notebook_01.","conceptArea":"Implement/manage – Notebook orchestration","notes":["Invalid answer set: no two listed choices fully implement the required dependency chain."],"refs":["R24"]},{"n":54,"batch":3,"question":"You have a Fabric workspace that contains a data pipeline named Pipeline1 as shown in the exhibit.\n(Click the Exhibit tab.)\n\nWhat will occur the next time Pipeline1 runs?\n\nA. Copy_kdi will run first, and then Execute procedure1 will run.\nB. Execute procedure1 will run first, and then Copy_kdi will run.\nC. Execute procedure1 will run and Copy_kdi will be skipped.\nD. Copy_kdi will run and Execute procedure1 will be skipped.\nE. Both activities will run simultaneously.\nF. Both activities will be skipped.\n\nExhibit: Copy_kdi shows Succeeded/active; Execute procedure1 shows Inactive; the activities have no dependency link.","options":[{"label":"A","text":"Copy_kdi will run first, and then Execute procedure1 will run."},{"label":"B","text":"Execute procedure1 will run first, and then Copy_kdi will run."},{"label":"C","text":"Execute procedure1 will run and Copy_kdi will be skipped."},{"label":"D","text":"Copy_kdi will run and Execute procedure1 will be skipped."},{"label":"E","text":"Both activities will run simultaneously."},{"label":"F","text":"Both activities will be skipped.\n\nExhibit: Copy_kdi shows Succeeded/active; Execute procedure1 shows Inactive; the activities have no dependency link."}],"originalAnswer":"F","correctAnswer":"D. Copy_kdi will run and Execute procedure1 will be skipped.","status":"Wrong","explanation":"The exhibit shows Copy_kdi as active/succeeded and Execute procedure1 as inactive. An inactive pipeline activity is skipped on the next run; the active, unblocked Copy activity runs.","conceptArea":"Implement/manage – Pipeline activity state","notes":[],"refs":["R28"]},{"n":55,"batch":3,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a warehouse named Warehouse1. Warehouse1 contains a\ntable named Customer. Customer contains the following data.\n\nYou have an internal Microsoft Entra user named User1 that has an email address of\nuser1@contoso.com.\nYou need to provide User1 with access to the Customer table. The solution must prevent User1 from\naccessing the CreditCard column.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"SELECT; [User1]","correctAnswer":"`GRANT SELECT ON Customers(CustomerID, FirstName, LastName, Phone) TO [user1@contoso.com];`","status":"Wrong","explanation":"The column list correctly omits CreditCard, but Fabric's documented Entra-user principal form is the user's email/UPN. `[User1]` is not the principal identified by the question; `[user1@contoso.com]` is.","conceptArea":"Implement/manage – Column-level security","notes":[],"refs":["R27"]},{"n":56,"batch":3,"question":"You have a Fabric deployment pipeline that uses three workspaces named Dev, Test, and Prod.\nYou need to deploy an Eventhouse as part of the deployment process.\nWhat should you use to add the Eventhouse to the deployment process?\n\nA. an Azure DevOps pipeline\nB. an eventstream\nC. GitHub Actions","options":[{"label":"A","text":"an Azure DevOps pipeline"},{"label":"B","text":"an eventstream"},{"label":"C","text":"GitHub Actions"}],"originalAnswer":"A","correctAnswer":"A Fabric deployment pipeline (not present in the choices).","status":"Wrong","explanation":"Eventhouse is currently supported by Fabric deployment pipelines. Azure DevOps was a workaround for an older limitation; because the correct current option is absent, the item is now invalid.","conceptArea":"Implement/manage – Deployment pipelines","notes":["Outdated/invalid options."],"refs":["R8"]},{"n":57,"batch":3,"question":"You have a Fabric warehouse named DW1. DW1 contains a table that stores sales data and is used by\nmultiple sales representatives.\nYou plan to implement row-level security (RLS).\nYou need to ensure that the sales representatives can see only their respective data.\nWhich warehouse object do you require to implement RLS?\n\nA. TRIGGER\nB. SCHEMA\nC. FUNCTION\nD. DATABASE ROLE","options":[{"label":"A","text":"TRIGGER"},{"label":"B","text":"SCHEMA"},{"label":"C","text":"FUNCTION"},{"label":"D","text":"DATABASE ROLE"}],"originalAnswer":"C","correctAnswer":"C. FUNCTION.","status":"Correct","explanation":"The inline table-valued predicate function contains the RLS filtering logic.","conceptArea":"Implement/manage – Security (RLS)","notes":[],"refs":["R7"]},{"n":58,"batch":3,"question":"You have a Fabric warehouse named DW1. DW1 contains a table that stores sales data and is used by\nmultiple sales representatives.\nYou plan to implement row-level security (RLS).\nYou need to ensure that the sales representatives can see only their respective data.\nWhich warehouse object do you require to implement RLS?\n\nA. SECURITY POLICY\nB. TABLE\nC. TRIGGER\nD. STORED PROCEDURE","options":[{"label":"A","text":"SECURITY POLICY"},{"label":"B","text":"TABLE"},{"label":"C","text":"TRIGGER"},{"label":"D","text":"STORED PROCEDURE"}],"originalAnswer":"A","correctAnswer":"A. SECURITY POLICY.","status":"Correct","explanation":"A security policy attaches and enforces the RLS predicate function on the target table.","conceptArea":"Implement/manage – Security (RLS)","notes":[],"refs":["R7"]},{"n":59,"batch":3,"question":"You have a Fabric F32 capacity that contains a workspace. The workspace contains a warehouse named\nDW1 that is modelled by using MD5 hash surrogate keys.\nDW1 contains a single fact table that has grown from 200 million rows to 500 million rows during the past\nyear.\nYou have Microsoft Power BI reports that are based on Direct Lake. The reports show year-over-year\nvalues.\nUsers report that the performance of some of the reports has degraded over time and some visuals show\nerrors.\n\nYou need to resolve the performance issues. The solution must meet the following requirements:\nProvide the best query performance.\nMinimize operational costs.\nWhich should you do?\n\nA. Create views.\nB. Modify the surrogate keys to use a different data type.\nC. Change the MD5 hash to SHA256.\nD. Increase the capacity.\nE. Disable V-Order on the warehouse.","options":[{"label":"A","text":"Create views."},{"label":"B","text":"Modify the surrogate keys to use a different data type."},{"label":"C","text":"Change the MD5 hash to SHA256."},{"label":"D","text":"Increase the capacity."},{"label":"E","text":"Disable V-Order on the warehouse."}],"originalAnswer":"D","correctAnswer":"D. Increase the capacity.","status":"Correct","explanation":"As in Question 8, the fact table exceeds the lower Direct Lake guardrail assumed by the scenario. Increasing capacity is the listed action that restores the higher-capacity Direct Lake path; changing hash algorithms or disabling V-Order does not solve the capacity limit.","conceptArea":"Monitor/optimize – Direct Lake capacity","notes":["Capacity guardrails can change; confirm current SKU limits when sizing."],"refs":["R5"]},{"n":60,"batch":3,"question":"You have a Fabric workspace named Workspace1 that contains a warehouse named Warehouse1.\nYou plan to deploy Warehouse 1 to a new workspace named Workspace2.\nAs part of the deployment process, you need to verify whether Warehouse1 contains invalid references.\nThe solution must minimize development effort and provide detailed information about the invalid\nreferences.\nWhat should you use?\n\nA. a dbt project\nB. a deployment pipeline\nC. a Python script\nD. a database project","options":[{"label":"A","text":"a dbt project"},{"label":"B","text":"a deployment pipeline"},{"label":"C","text":"a Python script"},{"label":"D","text":"a database project"}],"originalAnswer":"B","correctAnswer":"D. A database project.","status":"Wrong","explanation":"A database-project build validates references and provides detailed diagnostics. Deployment pipelines do not perform the requested detailed schema-reference validation.","conceptArea":"Implement/manage – Warehouse CI/CD","notes":[],"refs":["R10"]},{"n":61,"batch":3,"question":"You need to create a workflow for the new book cover images.\nWhich two components should you include in the workflow? Each correct answer presents part of the\nsolution.\nNote: Each correct selection is worth one point.\n\nA. an activator item\nB. a data pipeline\nC. a blob storage action\nD. a time-based schedule\nE. a streaming dataflow\nF. a notebook that uses Apache Spark Structured Streaming","options":[{"label":"A","text":"an activator item"},{"label":"B","text":"a data pipeline"},{"label":"C","text":"a blob storage action"},{"label":"D","text":"a time-based schedule"},{"label":"E","text":"a streaming dataflow"},{"label":"F","text":"a notebook that uses Apache Spark Structured Streaming"}],"originalAnswer":"C, E","correctAnswer":"A and B. An Activator item and a data pipeline.","status":"Wrong","explanation":"OneLake file-created events can feed an Activator rule whose Run a Fabric item action starts a pipeline immediately. A blob-storage action plus streaming dataflow is neither the current Fabric-only event/action pattern nor the best fit for image-file processing.","conceptArea":"Implement/manage – Event-driven orchestration","notes":[],"refs":["R14"]},{"n":62,"batch":3,"question":"You need to create a workflow for the new book cover images.\nWhich two components should you include in the workflow? Each correct answer presents part of the\nsolution.\nNote: Each correct selection is worth one point.\n\nA. a time-based schedule\nB. a streaming dataflow\nC. a blob storage action\nD. a data pipeline\nE. a notebook that uses Apache Spark Structured Streaming\nF. a reflex item","options":[{"label":"A","text":"a time-based schedule"},{"label":"B","text":"a streaming dataflow"},{"label":"C","text":"a blob storage action"},{"label":"D","text":"a data pipeline"},{"label":"E","text":"a notebook that uses Apache Spark Structured Streaming"},{"label":"F","text":"a reflex item"}],"originalAnswer":"B, C","correctAnswer":"D and F. A data pipeline and a reflex item (the former name for Activator).","status":"Wrong","explanation":"In the terminology used by this older item, a reflex receives the file event and runs the data pipeline. Streaming dataflow and blob-storage action do not provide the required OneLake event-to-processing workflow.","conceptArea":"Implement/manage – Event-driven orchestration","notes":["Outdated terminology: Reflex is now Fabric Activator."],"refs":["R14"]},{"n":63,"batch":3,"question":"What should you recommend that the data engineering team use to ingest the SEO data?\n\nA. a streaming dataflow\nB. a streaming dataset\nC. a notebook that uses Apache Spark Structured Streaming\nD. an eventstream","options":[{"label":"A","text":"a streaming dataflow"},{"label":"B","text":"a streaming dataset"},{"label":"C","text":"a notebook that uses Apache Spark Structured Streaming"},{"label":"D","text":"an eventstream"}],"originalAnswer":"D","correctAnswer":"D. An eventstream.","status":"Correct","explanation":"Eventstream is the low-code Fabric item for near-real-time REST/HTTP ingestion and routing. The HTTP connector is currently documented as a commonly used preview capability, so production use should consider its preview status.","conceptArea":"Ingest/transform – Real-time ingestion","notes":[],"refs":["R29","R49"]},{"n":64,"batch":3,"question":"You need to implement the solution for the book reviews.\nWhich should you do?\n\nA. Create a Dataflow Gen2 dataflow.\nB. Create a shortcut.\nC. Enable external data sharing.\nD. Create a data pipeline.","options":[{"label":"A","text":"Create a Dataflow Gen2 dataflow."},{"label":"B","text":"Create a shortcut."},{"label":"C","text":"Enable external data sharing."},{"label":"D","text":"Create a data pipeline."}],"originalAnswer":"B","correctAnswer":"B. Create a shortcut.","status":"Correct","explanation":"A OneLake shortcut exposes the S3 data without copying it into the lakehouse, directly satisfying the no-copy requirement.","conceptArea":"Ingest/transform – OneLake shortcuts","notes":[],"refs":["R12"]},{"n":65,"batch":3,"question":"You need to resolve the sales data issue. The solution must minimize the amount of data transferred.\nWhat should you do?\n\nA. Spilt the dataflow into two dataflows.\nB. Configure scheduled refresh for the dataflow.\nC. Configure incremental refresh for the dataflow. Set Store rows from the past to 1 Month.\nD. Configure incremental refresh for the dataflow. Set Refresh rows from the past to 1 Year.\nE. Configure incremental refresh for the dataflow. Set Refresh rows from the past to 1 Month.","options":[{"label":"A","text":"Spilt the dataflow into two dataflows."},{"label":"B","text":"Configure scheduled refresh for the dataflow."},{"label":"C","text":"Configure incremental refresh for the dataflow. Set Store rows from the past to 1 Month."},{"label":"D","text":"Configure incremental refresh for the dataflow. Set Refresh rows from the past to 1 Year."},{"label":"E","text":"Configure incremental refresh for the dataflow. Set Refresh rows from the past to 1 Month."}],"originalAnswer":"E","correctAnswer":"E. Configure incremental refresh to refresh rows from the past one month.","status":"Correct","explanation":"The source refreshes throughout the day, while records older than a month never change. Refreshing only the most recent month captures changes and minimizes transferred historical data.","conceptArea":"Ingest/transform – Dataflow incremental refresh","notes":[],"refs":["R31"]},{"n":66,"batch":3,"question":"HOTSPOT (Drag and Drop is not supported)\nYou need to recommend a method to populate the POS1 data to the lakehouse medallion layers.\nWhat should you recommend for each layer? To answer, select the appropriate options in the answer\narea.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Bronze: Copy activity; Silver: Notebook","correctAnswer":"Bronze: pipeline Copy activity. Silver: notebook.","status":"Correct","explanation":"Copy activity lands source data with no business transformation and can convert only the file format for bronze. A notebook provides the flexible deduplication, missing-value handling, and capitalization logic required for silver.","conceptArea":"Ingest/transform – Medallion architecture","notes":[],"refs":["R32","R35"]},{"n":67,"batch":3,"question":"You need to ensure that usage of the data in the Amazon S3 bucket meets the technical requirements.\nWhat should you do?\n\nA. Create a workspace identity and enable high concurrency for the notebooks.\nB. Create a shortcut and ensure that caching is disabled for the workspace.\nC. Create a workspace identity and use the identity in a data pipeline.\nD. Create a shortcut and ensure that caching is enabled for the workspace.","options":[{"label":"A","text":"Create a workspace identity and enable high concurrency for the notebooks."},{"label":"B","text":"Create a shortcut and ensure that caching is disabled for the workspace."},{"label":"C","text":"Create a workspace identity and use the identity in a data pipeline."},{"label":"D","text":"Create a shortcut and ensure that caching is enabled for the workspace."}],"originalAnswer":"D","correctAnswer":"D. Create an S3 shortcut and enable shortcut caching.","status":"Correct","explanation":"The shortcut avoids persisting a lakehouse copy, while cache reduces repeated cross-cloud reads and therefore egress. A pipeline or workspace identity would copy/read the source rather than satisfy both requirements as directly.","conceptArea":"Implement/manage – Shortcut cache and cost","notes":[],"refs":["R12"]},{"n":68,"batch":3,"question":"HOTSPOT (Drag and Drop is not supported)\nYou need to create the product dimension.\nHow should you complete the Apache Spark SQL code? To answer, select the appropriate options in the\nanswer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"INNER JOIN; INNER JOIN; IsActive = 1","correctAnswer":"INNER JOIN Products→ProductSubcategories; INNER JOIN ProductSubcategories→ProductCategories; WHERE IsActive = 1.","status":"Correct","explanation":"Inner joins omit unassigned categories/subcategories and retain only products with complete matches. The IsActive filter restricts the dimension to active products.","conceptArea":"Ingest/transform – Dimensional modeling","notes":[],"refs":["R6"]},{"n":69,"batch":3,"question":"You need to populate the MAR1 data in the bronze layer.\nWhich two types of activities should you include in the pipeline? Each correct answer presents part of the\nsolution.\nNote: Each correct selection is worth one point.\n\nA. ForEach\nB. Copy data\nC. WebHook\nD. Stored procedure","options":[{"label":"A","text":"ForEach"},{"label":"B","text":"Copy data"},{"label":"C","text":"WebHook"},{"label":"D","text":"Stored procedure"}],"originalAnswer":"A, B","correctAnswer":"A and B. ForEach and Copy data.","status":"Correct","explanation":"ForEach iterates MAR1's seven endpoints and a parameterized Copy activity uses the built-in connector to land each entity in bronze with minimal custom code.","conceptArea":"Ingest/transform – Metadata-driven ingestion","notes":[],"refs":["R35"]},{"n":70,"batch":3,"question":"You need to recommend a solution to resolve the MAR1 connectivity issues. The solution must minimize\ndevelopment effort.\nWhat should you recommend?\n\nA. Add a ForEach activity to the data pipeline.\nB. Configure retries for the Copy data activity.\nC. Call a notebook from the data pipeline.\nD. Configure Fault tolerance for the Copy data activity.","options":[{"label":"A","text":"Add a ForEach activity to the data pipeline."},{"label":"B","text":"Configure retries for the Copy data activity."},{"label":"C","text":"Call a notebook from the data pipeline."},{"label":"D","text":"Configure Fault tolerance for the Copy data activity."}],"originalAnswer":"B","correctAnswer":"B. Configure retries for the Copy data activity.","status":"Correct","explanation":"Activity retry settings address transient connectivity failures with the least development effort. Fault tolerance concerns bad rows/files rather than connection retry behavior.","conceptArea":"Implement/manage – Pipeline reliability","notes":[],"refs":["R35"]},{"n":71,"batch":3,"question":"You need to recommend a solution for handling old files. The solution must meet the technical\nrequirements.\nWhat should you include in the recommendation?\n\nA. a data pipeline that includes a Copy data activity\nB. a data pipeline that includes a Delete data activity\nC. a notebook that runs the VACUUM command\nD. a notebook that runs the OPTIMIZE command","options":[{"label":"A","text":"a data pipeline that includes a Copy data activity"},{"label":"B","text":"a data pipeline that includes a Delete data activity"},{"label":"C","text":"a notebook that runs the VACUUM command"},{"label":"D","text":"a notebook that runs the OPTIMIZE command"}],"originalAnswer":"C","correctAnswer":"C. A notebook that runs VACUUM.","status":"Correct","explanation":"VACUUM removes obsolete files no longer referenced by the Delta log; OPTIMIZE compacts active files and does not perform the required retention cleanup.","conceptArea":"Monitor/optimize – Delta maintenance","notes":[],"refs":["R19"]},{"n":72,"batch":3,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a warehouse named Warehouse1. Warehouse1 contains the\nfollowing tables and columns.\n\nYou need to denormalize the tables and include the ContractType and StartDate columns in the\nEmployee table. The solution must meet the following requirements:\nEnsure that the StartDate column is of the date data type.\nEnsure that all the rows from the Employee table are preserved and include any matching rows from the\nContract table.\nEnsure that the result set displays the total number of employees per contract type for all the contract\ntypes that have more than two employees.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"CAST; LEFT OUTER JOIN; HAVING","correctAnswer":"CAST; LEFT OUTER JOIN; HAVING.","status":"Correct","explanation":"CAST converts StartDate to date, LEFT OUTER JOIN preserves every Employee row, and HAVING filters aggregated contract-type groups to counts greater than two.","conceptArea":"Ingest/transform – Warehouse T-SQL","notes":[],"refs":["R6"]},{"n":73,"batch":3,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have an Azure Event Hubs data source that contains weather data.\nYou ingest the data from the data source by using an eventstream named Eventstream1. Eventstream1\nuses a lakehouse as the destination.\nYou need to batch ingest only rows from the data source where the City attribute has a value of Kansas.\nThe filter must be added before the destination. The solution must minimize development effort.\nWhat should you use for the data processor and filtering? To answer, select the appropriate options in the\nanswer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Dataflow Gen2; filter in Dataflow Gen2","correctAnswer":"Data processor: an eventstream with an external data source. Filtering: an eventstream processor.","status":"Wrong","explanation":"The Event Hubs source is already streaming through Eventstream1, and Eventstream's processor can filter City = 'Kansas' before the lakehouse destination. A separate Dataflow Gen2 batch path does not process the existing stream and adds unnecessary effort.","conceptArea":"Ingest/transform – Eventstream processing","notes":[],"refs":["R29","R30"]},{"n":74,"batch":3,"question":"You have a Fabric workspace that contains an eventstream named Eventstream1. Eventstream1\nprocesses data from a thermal sensor by using event stream processing, and then stores the data in a\nlakehouse.\nYou need to modify Eventstream1 to include the standard deviation of the temperature.\nWhich transform operator should you include in the Eventstream1 logic?\n\nA. Expand\nB. Group by\nC. Union\nD. Aggregate","options":[{"label":"A","text":"Expand"},{"label":"B","text":"Group by"},{"label":"C","text":"Union"},{"label":"D","text":"Aggregate"}],"originalAnswer":"B","correctAnswer":"B. Group by.","status":"Correct","explanation":"Standard deviation is an aggregate calculated over a group/window. Eventstream's grouping operation is the operator that defines grouping and exposes STDEV/STDEVP-style aggregations.","conceptArea":"Ingest/transform – Eventstream processing","notes":[],"refs":["R29"]},{"n":75,"batch":3,"question":"You have an Azure event hub. Each event contains the following fields:\nBikepointID\nStreet\nNeighbourhood\nLatitude\nLongitude\nNo_Bikes\nNo_Empty_Docks\nYou need to ingest the events. The solution must only retain events that have a Neighbourhood value of\nChelsea, and then store the retained events in a Fabric lakehouse.\nWhat should you use?\n\nA. a KQL queryset\nB. an eventstream\nC. a streaming dataset\nD. Apache Spark Structured Streaming","options":[{"label":"A","text":"a KQL queryset"},{"label":"B","text":"an eventstream"},{"label":"C","text":"a streaming dataset"},{"label":"D","text":"Apache Spark Structured Streaming"}],"originalAnswer":"B","correctAnswer":"B. An eventstream.","status":"Correct","explanation":"Eventstream connects to Event Hubs, applies a filter, and writes the retained stream to a lakehouse with low-code event processing.","conceptArea":"Ingest/transform – Real-time ingestion","notes":[],"refs":["R30"]},{"n":76,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou are building a data loading pattern for Fabric notebook workloads.\nYou have the following code segment:\n\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"No; No; Yes","correctAnswer":"No; No; Yes.","status":"Correct","explanation":"The table is overwritten only for initial creation, while MERGE runs only when the target exists. Together those branches support initial/full creation plus incremental upsert behavior.","conceptArea":"Ingest/transform – Delta loading","notes":[],"refs":["R37"]},{"n":77,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains two lakehouses named Lakehouse1 and Lakehouse2.\nLakehouse1 contains staging data in a Delta table named Orderlines. Lakehouse2 contains a Type 2\nslowly changing dimension (SCD) dimension table named Dim_Customer.\nYou need to build a query that will combine data from Orderlines and Dim_Customer to create a new fact\ntable named Fact_Orders. The new table must meet the following requirements:\nEnable the analysis of customer orders based on historical attributes.\nEnable the analysis of customer orders based on the current attributes.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"OrderDate >= valid_from; OrderDate < valid_to","correctAnswer":"`o.OrderDate >= c.valid_from_datetime` and `o.OrderDate < c.valid_to_datetime`.","status":"Correct","explanation":"The half-open effective-date range selects the historical Type 2 row valid at the order date. Including both the dimension surrogate key and the natural customer ID in the fact supports historical analysis and a separate join to the current dimension row; the supplied narrative's suggestion to filter this load on is_current would defeat historical matching.","conceptArea":"Ingest/transform – SCD Type 2","notes":[],"refs":["R6"]},{"n":78,"batch":4,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1.\nIn an external data source, you have data files that are 500 GB each. A new file is added every day.\nYou need to ingest the data into Lakehouse1 without applying any transformations. The solution must\nmeet the following requirements\nTrigger the process when a new file is added.\nProvide the highest throughput.\nWhich type of item should you use to ingest the data?\n\nA. Eventstream\nB. Dataflow Gen2\nC. Streaming dataset\nD. Data pipeline","options":[{"label":"A","text":"Eventstream"},{"label":"B","text":"Dataflow Gen2"},{"label":"C","text":"Streaming dataset"},{"label":"D","text":"Data pipeline"}],"originalAnswer":"D","correctAnswer":"D. Data pipeline.","status":"Correct","explanation":"For a 500-GB file requiring no transformations, pipeline copy provides the high-throughput data movement path and supports event-based execution when a file arrives.","conceptArea":"Ingest/transform – Large-file ingestion","notes":[],"refs":["R28","R35"]},{"n":79,"batch":4,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1.\n\nIn an external data source, you have data files that are 500 GB each. A new file is added every day.\nYou need to ingest the data into Lakehouse1 without applying any transformations. The solution must\nmeet the following requirements\nTrigger the process when a new file is added.\nProvide the highest throughput.\nWhich type of item should you use to ingest the data?\n\nA. Data pipeline\nB. Environment\nC. KQL queryset\nD. Dataflow Gen2","options":[{"label":"A","text":"Data pipeline"},{"label":"B","text":"Environment"},{"label":"C","text":"KQL queryset"},{"label":"D","text":"Dataflow Gen2"}],"originalAnswer":"A","correctAnswer":"A. Data pipeline.","status":"Correct","explanation":"The data pipeline is the listed item that combines scalable copy with file-arrival triggering.","conceptArea":"Ingest/transform – Large-file ingestion","notes":[],"refs":["R28","R35"]},{"n":80,"batch":4,"question":"You have a Fabric workspace that contains an eventhouse and a KQL database named Database1.\nDatabase1 has the following:\nA table named Table1\nA table named Table2\nAn update policy named Policy1\nPolicy1 sends data from Table1 to Table2.\nThe following is a sample of the data in Table2.\n\nRecently, the following actions were performed on Table1:\nAn additional element named temperature was added to the StreamData column.\nThe data type of the Timestamp column was changed to date.\nThe data type of the DeviceId column was changed to string.\nYou plan to load additional records to Table2.\nWhich two records will load from Table1 to Table2? Each correct answer presents a complete solution.\nNote: Each correct selection is worth one point.\n\nA.\n\nB.\n\nC.\n\nD.\n\nRecord exhibits: A has a valid full GUID and dynamic data with `temperature`; B has DeviceId `81416f30`; C has a malformed overlong GUID-like string; D has a valid full GUID.","options":[{"label":"A","text":"B."},{"label":"C","text":"D.\n\nRecord exhibits: A has a valid full GUID and dynamic data with `temperature`; B has DeviceId `81416f30`; C has a malformed overlong GUID-like string; D has a valid full GUID."}],"originalAnswer":"B, D","correctAnswer":"A and D.","status":"Wrong","explanation":"A and D contain valid GUID-shaped DeviceId values; B's shortened value and C's malformed value cannot populate a guid target. The dynamic StreamData column can hold an added temperature property, and a date value can be represented at midnight in the datetime target, so A remains valid.","conceptArea":"Ingest/transform – KQL schema and update policy","notes":[],"refs":["R34"]},{"n":81,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace.\nYou are debugging a statement and discover the following issues:\n\nSometimes, the statement fails to return all the expected rows.\nThe PurchaseDate output column is NOT in the expected format of mmm dd, yy.\nYou need to resolve the issues. The solution must ensure that the data types of the results are retained.\nThe results can contain blank cells.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"try_cast(...varchar(20)); convert(varchar,purchase_date,7)","correctAnswer":"`try_cast(item_name AS varchar(20))`; `convert(varchar, purchase_date, 7)`.","status":"Correct","explanation":"TRY_CAST returns NULL rather than dropping/failing the row when conversion is impossible, which the question permits as a blank. CONVERT style 7 produces the requested `Mon dd, yy` display form.","conceptArea":"Ingest/transform – Warehouse T-SQL","notes":[],"refs":["R6"]},{"n":82,"batch":4,"question":"You are developing a data pipeline named Pipeline1.\nYou need to add a Copy data activity that will copy data from a Snowflake data source to a Fabric\nwarehouse.\nWhich option from the Settings tab of the Copy data activity must you configure?\n\nA. Degree of copy parallelism\nB. Fault tolerance\nC. Enable staging\nD. Enable logging","options":[{"label":"A","text":"Degree of copy parallelism"},{"label":"B","text":"Fault tolerance"},{"label":"C","text":"Enable staging"},{"label":"D","text":"Enable logging"}],"originalAnswer":"C","correctAnswer":"C. Enable staging.","status":"Correct","explanation":"The Snowflake-to-Warehouse copy path uses staging to enable the optimized bulk-load pattern between those stores.","conceptArea":"Ingest/transform – Copy activity","notes":[],"refs":["R35"]},{"n":83,"batch":4,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a KQL database that contains two tables named Stream and Reference. Stream contains\nstreaming data in the following format.\n\nReference contains reference data in the following format.\n\nBoth tables contain millions of rows.\nYou have the following KQL queryset.\n\nYou need to reduce how long it takes to run the KQL queryset.\nSolution: You change the join type to kind=outer.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"Changing to an outer join increases retained rows and does not reduce the millions-row join workload. It is not a performance optimization for this query.","conceptArea":"Monitor/optimize – KQL query tuning","notes":[],"refs":["R23"]},{"n":84,"batch":4,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a KQL database that contains two tables named Stream and Reference. Stream contains\nstreaming data in the following format.\n\nReference contains reference data in the following format.\n\nBoth tables contain millions of rows.\nYou have the following KQL queryset.\n\nYou need to reduce how long it takes to run the KQL queryset.\nSolution: You change project to extend.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"Replacing project with extend retains additional columns and does not reduce data volume. Project is preferable when only selected output columns are needed.","conceptArea":"Monitor/optimize – KQL query tuning","notes":[],"refs":["R23"]},{"n":85,"batch":4,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a KQL database that contains two tables named Stream and Reference. Stream contains\nstreaming data in the following format.\n\nReference contains reference data in the following format.\n\nBoth tables contain millions of rows.\nYou have the following KQL queryset.\n\nYou need to reduce how long it takes to run the KQL queryset.\nSolution: You move the filter to line 02.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"A","correctAnswer":"A. Yes.","status":"Correct","explanation":"Pushing the filter before the join reduces rows entering the large join, which is a standard and effective KQL optimization.","conceptArea":"Monitor/optimize – KQL query tuning","notes":[],"refs":["R23"]},{"n":86,"batch":4,"question":"Note: This question is part of a series of questions that present the same scenario. Each question in the\nseries contains a unique solution that might meet the stated goals. Some question sets might have more\nthan one correct solution, while others might not have a correct solution.\nAfter you answer a question in this section, you will NOT be able to return to it. As a result, these\nquestions will not appear in the review screen.\nYou have a KQL database that contains two tables named Stream and Reference. Stream contains\nstreaming data in the following format.\n\nReference contains reference data in the following format.\n\nBoth tables contain millions of rows.\nYou have the following KQL queryset.\n\nYou need to reduce how long it takes to run the KQL queryset.\nSolution: You add the make_list() function to the output columns.\nDoes this meet the goal?\n\nA. Yes\nB. No","options":[{"label":"A","text":"Yes"},{"label":"B","text":"No"}],"originalAnswer":"B","correctAnswer":"B. No.","status":"Correct","explanation":"make_list introduces aggregation, memory use, and output construction; it does not reduce the query runtime for the stated join.","conceptArea":"Monitor/optimize – KQL query tuning","notes":[],"refs":["R23"]},{"n":87,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric warehouse named DW1 that contains four staging tables named ProductCategory,\nProductSubcategory, Product, and SalesOrder. ProductCategory, ProductSubcategory, and Product are\nused often in analytical queries.\nYou need to implement a star schema for DW1. The solution must minimize development effort.\nWhich design approach should you use? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nAnswer choices include: individual snowflake tables, denormalize into SalesOrder, or one product dimension; key choices are product name+date, unique system-generated identifier, or category name.","options":[{"label":"A","text":"See Explanation section for answer.\n\nAnswer choices include: individual snowflake tables, denormalize into SalesOrder, or one product dimension; key choices are product name+date, unique system-generated identifier, or category name."}],"originalAnswer":"Single denormalized product dimension; product name and date key","correctAnswer":"Denormalize the three product tables into one product dimension; join it to the fact by a unique system-generated identifier.","status":"Wrong","explanation":"The supplied denormalization choice is correct, but product name plus date is not a stable dimension key. A generated surrogate key is the appropriate fact-to-dimension join key and minimizes ambiguity when attributes change.","conceptArea":"Ingest/transform – Star schema","notes":[],"refs":["R6"]},{"n":88,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\n\nYour company has three newly created data engineering teams named Team1, Team2, and Team3 that\nplan to use Fabric. The teams have the following personas:\nTeam1 consists of members who currently use Microsoft Power BI. The team wants to transform data by\nusing by a low-code approach.\nTeam2 consists of members that have a background in Python programming. The team wants to use\nPySpark code to transform data.\nTeam3 consists of members who currently use Azure Data Factory. The team wants to move data\nbetween source and sink environments by using the least amount of effort.\nYou need to recommend tools for the teams based on their current personas.\nWhat should you recommend for each team? To answer, select the appropriate options in the answer\narea.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Dataflow Gen2; Notebook; Data pipeline","correctAnswer":"Team1: Dataflow Gen2; Team2: Notebook; Team3: Data pipeline.","status":"Correct","explanation":"Dataflow Gen2 matches the Power Query/low-code persona, notebooks support PySpark, and pipelines provide the Azure Data Factory-like copy/orchestration experience.","conceptArea":"Ingest/transform – Tool selection","notes":[],"refs":["R28","R35"]},{"n":89,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou plan to process the following three datasets by using Fabric:\nDataset1: This dataset will be added to Fabric and will have a unique primary key between the source\n\nand the destination. The unique primary key will be an integer and will start from 1 and have an increment\nof 1. Dataset2: This dataset contains semi-structured data that uses bulk data transfer. The dataset must\nbe handled in one process between the source and the destination. The data transformation process will\ninclude the use of custom visuals to understand and work with the dataset in development mode.\nDataset3: This dataset is in a lakehouse. The data will be bulk loaded. The data transformation process\nwill include row-based windowing functions during the loading process.\nYou need to identify which type of item to use for the datasets. The solution must minimize development\neffort and use built-in functionality, when possible.\nWhat should you identify for each dataset? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nAnswer choices: Dataset1—Dataflow Gen2/Notebook/T-SQL; Dataset2—Dataflow Gen2/Notebook/T-SQL; Dataset3—Dataflow Gen2/KQL queryset/T-SQL.","options":[{"label":"A","text":"See Explanation section for answer.\n\nAnswer choices: Dataset1—Dataflow Gen2/Notebook/T-SQL; Dataset2—Dataflow Gen2/Notebook/T-SQL; Dataset3—Dataflow Gen2/KQL queryset/T-SQL."}],"originalAnswer":"T-SQL; Notebook; Dataflow Gen2","correctAnswer":"Dataset1: Dataflow Gen2 (Add Index); Dataset2: Notebook; Dataset3: Notebook, which is not listed.","status":"Wrong","explanation":"Dataflow Gen2 can add an integer index starting at 1, while current Fabric Warehouse IDENTITY does not support a chosen seed/increment and only supports bigint. A notebook suits the semi-structured visualization case and is also the current supported choice for lakehouse row-based windowing; Microsoft explicitly notes that the Mapping Data Flow Window transform is not supported in Dataflow Gen2, so the item has no fully correct listed answer.","conceptArea":"Ingest/transform – Tool selection","notes":["Invalid/outdated answer set for Dataset3."],"refs":["R36","R45"]},{"n":90,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains a lakehouse named Lakehouse1. Lakehouse1 contains a\ntable named Status_Target that has the following columns:\nKey\nStatus\nLastModified\nThe data source contains a table named Status_Source that has the same columns as Status_Target.\nStatus_Source is used to populate Status_Target.\nIn a notebook name Notebook1, you load Status_Source to a DataFrame named sourceDF and\nStatus_Target to a DataFrame named targetDF.\nYou need to implement an incremental loading pattern by using Notebook1. The solution must meet the\n\nfollowing requirements:\nFor all the matching records that have the same value of key, update the value of LastModified in\nStatus_Target to the value of LastModified in Status_Source. Insert all the records that exist in\nStatus_Source that do NOT exist in Status_Target.\nSet the value of Status in Status_Target to inactive for all the records that were last modified more than\nseven days ago and that do NOT exist in Status_Source.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"whenMatchedUpdate; whenNotMatchedInsert; whenNotMatchedBySourceUpdate","correctAnswer":"whenMatchedUpdate; whenNotMatchedInsert; whenNotMatchedBySourceUpdate.","status":"Correct","explanation":"The three Delta MERGE clauses respectively update matching rows, insert source-only rows, and update target-only stale rows to inactive.","conceptArea":"Ingest/transform – Delta MERGE","notes":[],"refs":["R37"]},{"n":91,"batch":4,"question":"DRAG DROP (Drag and Drop is not supported)\nYou are building a data loading pattern by using a Fabric data pipeline. The source is an Azure SQL\ndatabase that contains 25 tables. The destination is a lakehouse.\nIn a warehouse, you create a control table named Control.Object as shown in the exhibit. (Click the\nExhibit tab.)\n\nYou need to build a data pipeline that will support the dynamic ingestion of the tables listed in the control\ntable by using a single execution.\nWhich three actions should you perform in sequence? To answer, move the appropriate actions from the\nlist of actions to the answer area and arrange them in the correct order.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"Lookup → ForEach → Copy data","correctAnswer":"Lookup → ForEach → Copy data.","status":"Correct","explanation":"Lookup reads the control-table rows, ForEach iterates the resulting array, and Copy data performs one parameterized table copy per iteration.","conceptArea":"Implement/manage – Metadata-driven pipeline","notes":[],"refs":["R35"]},{"n":92,"batch":4,"question":"You are implementing a medallion architecture in a Fabric lakehouse.\nYou plan to create a dimension table that will contain the following columns:\nID\nCustomerCode\nCustomerName\nCustomerAddress\nCustomerLocation\nValidFrom\nValidTo\nYou need to ensure that the table supports the analysis of historical sales data by customer location at\nthe time of each sale.\nWhich type of slowly changing dimension (SCD) should you use?\n\nA. Type 2\nB. Type 0\nC. Type 1\nD. Type 3","options":[{"label":"A","text":"Type 2"},{"label":"B","text":"Type 0"},{"label":"C","text":"Type 1"},{"label":"D","text":"Type 3"}],"originalAnswer":"A","correctAnswer":"A. Type 2.","status":"Correct","explanation":"Type 2 preserves location history by creating a new dimension row with validity dates when the customer location changes.","conceptArea":"Ingest/transform – Dimensional modeling","notes":[],"refs":["R6"]},{"n":93,"batch":4,"question":"You have a Fabric workspace that contains an eventstream named EventStream1. EventStream1 outputs\nevents to a table named Table1 in a lakehouse. The streaming data is sourced from motorway sensors\nand represents the speed of cars.\nYou need to add a transformation to EventStream1 to average the car speeds. The speeds must be\ngrouped by non-overlapping and contiguous time intervals of one minute. Each event must belong to\nexactly one window.\nWhich windowing function should you use?\n\nA. sliding\nB. hopping\nC. tumbling\nD. session","options":[{"label":"A","text":"sliding"},{"label":"B","text":"hopping"},{"label":"C","text":"tumbling"},{"label":"D","text":"session"}],"originalAnswer":"C","correctAnswer":"C. Tumbling window.","status":"Correct","explanation":"Tumbling windows are fixed, contiguous, and non-overlapping, so every event belongs to exactly one one-minute window.","conceptArea":"Ingest/transform – Stream windowing","notes":[],"refs":["R29"]},{"n":94,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a table in a Fabric lakehouse that contains the following data.\n\nYou have a notebook that contains the following code segment.\n\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nCode exhibit: line 01 replaces null/empty CustomerName; line 02 uses split(Email,'@').getItem(1); line 03 calls dropDuplicates(['OrderDate']) and also derives Year.","options":[{"label":"A","text":"See Explanation section for answer.\n\nCode exhibit: line 01 replaces null/empty CustomerName; line 02 uses split(Email,'@').getItem(1); line 03 calls dropDuplicates(['OrderDate']) and also derives Year."}],"originalAnswer":"Yes; No; Yes","correctAnswer":"Yes; No; No.","status":"Wrong","explanation":"Line 01 replaces null/empty customer names. Line 02 uses getItem(1), which returns the text after `@`, not before it; line 03 drops duplicates by full OrderDate, not by extracted Year, so it does not keep only one row per year.","conceptArea":"Ingest/transform – PySpark DataFrames","notes":[],"refs":["R24"]},{"n":95,"batch":4,"question":"You have a Fabric workspace that contains a warehouse named Warehouse1.\nYou have an on-premises Microsoft SQL Server database named Database1 that is accessed by using\nan on- premises data gateway.\nYou need to copy data from Database1 to Warehouse1.\nWhich item should you use?\n\nA. a data pipeline\nB. an Apache Spark job definition\nC. a streaming dataflow\nD. a notebook","options":[{"label":"A","text":"a data pipeline"},{"label":"B","text":"an Apache Spark job definition"},{"label":"C","text":"a streaming dataflow"},{"label":"D","text":"a notebook"}],"originalAnswer":"A","correctAnswer":"A. A data pipeline.","status":"Correct","explanation":"A pipeline Copy activity supports the on-premises gateway and Fabric Warehouse sink.","conceptArea":"Ingest/transform – Batch ingestion","notes":[],"refs":["R35"]},{"n":96,"batch":4,"question":"You have a Fabric warehouse named DW1 that contains a Type 2 slowly changing dimension (SCD)\ndimension table named DimCustomer. DimCustomer contains 100 columns and 20 million rows. The\ncolumns are of various data types, including int, varchar, date, and varbinary.\nYou need to identify incoming changes to the table and update the records when there is a change. The\nsolution must minimize resource consumption.\nWhat should you use to identify changes to attributes?\n\nA. a hash function to compare the attributes in the source table.\n\nB. a direct attributes comparison across the attributes in the DimCustomer table.\nC. a direct attributes comparison for the attributes in the source table.\nD. a hash function to compare the attributes in the DimCustomer table.","options":[{"label":"A","text":"a hash function to compare the attributes in the source table."},{"label":"B","text":"a direct attributes comparison across the attributes in the DimCustomer table."},{"label":"C","text":"a direct attributes comparison for the attributes in the source table."},{"label":"D","text":"a hash function to compare the attributes in the DimCustomer table."}],"originalAnswer":"D","correctAnswer":"A. Compute a hash across the incoming source attributes and compare it with the stored target hash.","status":"Wrong","explanation":"Hashing the 100 incoming attributes once and comparing a compact hash minimizes repeated column-by-column and target-side computation. Recomputing the hash across all 20 million target rows, as implied by D, consumes more resources; the question is somewhat terse, but the efficient SCD pattern stores a target hash and computes the source hash for incoming rows.","conceptArea":"Monitor/optimize – SCD change detection","notes":["Wording is ambiguous unless the target is understood to persist a previously calculated hash."],"refs":["R6"]},{"n":97,"batch":4,"question":"You have an Azure SQL database named DB1.\nIn a Fabric workspace, you deploy an eventstream named EventStreamDB1 to stream record changes\nfrom DB1 into a lakehouse.\nYou discover that events are NOT being propagated to EventStreamDB1.\nYou need to ensure that the events are propagated to EventStreamDB1.\nWhat should you do?\n\nA. Create a read-only replica of DB1.\nB. Create an Azure Stream Analytics job.\nC. Enable Extended Events for DB1.\nD. Enable change data capture (CDC) for DB1.","options":[{"label":"A","text":"Create a read-only replica of DB1."},{"label":"B","text":"Create an Azure Stream Analytics job."},{"label":"C","text":"Enable Extended Events for DB1."},{"label":"D","text":"Enable change data capture (CDC) for DB1."}],"originalAnswer":"D","correctAnswer":"D. Enable CDC for DB1.","status":"Correct","explanation":"The Eventstream Azure SQL CDC connector depends on database change data capture to emit row-level changes.","conceptArea":"Ingest/transform – CDC streaming","notes":[],"refs":["R38"]},{"n":98,"batch":4,"question":"DRAG DROP (Drag and Drop is not supported)\nYou have a Fabric workspace that contains an eventhouse named Eventhouse1.\nIn Eventhouse1, you plan to create a table named DeviceStreamData in a KQL database. The table will\ncontain data based on the following sample.\n\nYou need to use a KQL query to develop the solution for Eventhouse1.\nWhich three code segments should you run in sequence? To answer, move the appropriate code\nsegments from the list of code segments to the answer area and arrange them in the correct order.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"create table; datetime/string; dynamic","correctAnswer":"`.create table DeviceStreamData (` → `TimeStamp:datetime, DeviceID:string,` → `StreamData:dynamic)`.","status":"Correct","explanation":"The KQL table command and scalar types match the sample: timestamp, string device identifier, and a dynamic JSON-like payload.","conceptArea":"Ingest/transform – KQL schema","notes":[],"refs":["R29"]},{"n":99,"batch":4,"question":"DRAG DROP (Drag and Drop is not supported)\nYou have a KQL database that contains a table named Readings.\nYou need to build a KQL query to compare the MeterReading value of each row to the previous row base\non the Timestamp value.\nA sample of the expected output is shown in the following table.\n\nHow should you complete the query? To answer, drag the appropriate values the correct targets. Each\nvalue may be used once, more than once, or not at all. You may need to drag the split bar between panes\nor scroll to view content.\nNote: Each correct selection is worth one point.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"sort; extend; project","correctAnswer":"sort → extend → project.","status":"Correct","explanation":"Sort serializes rows in timestamp order, extend calculates the value derived from prev(MeterReading), and project returns the requested output columns.","conceptArea":"Ingest/transform – KQL window functions","notes":[],"refs":["R23"]},{"n":100,"batch":4,"question":"HOTSPOT (Drag and Drop is not supported)\nYou need to recommend a Fabric streaming solution that will use the sources shown in the following\ntable.\n\nThe solution must minimize development effort.\nWhat should you include in the recommendation for each source? To answer, select the appropriate\noptions in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nSource table: Source1 10-MB semi-structured messages with bigint; Source2 25-MB structured messages with 19 columns; Source3 5-MB unstructured messages containing images.","options":[{"label":"A","text":"See Explanation section for answer.\n\nSource table: Source1 10-MB semi-structured messages with bigint; Source2 25-MB structured messages with 19 columns; Source3 5-MB unstructured messages containing images."}],"originalAnswer":"Source1 Data pipeline; Source2 Spark Structured Streaming; Source3 streaming dataflow","correctAnswer":"Apache Spark Structured Streaming for Source1, Source2, and Source3, subject to the source connector/broker limits.","status":"Wrong","explanation":"Every message is larger than Eventstream's documented 1-MB event limit, and data pipelines are batch rather than streaming. Streaming dataflows are not a general binary-image transport; Spark Structured Streaming is the only listed general streaming engine able to parse large semi-structured, structured, and binary payloads, but the question omits source protocols and broker limits, so it cannot guarantee a single definitive production design.","conceptArea":"Ingest/transform – Streaming architecture","notes":["Ambiguous/invalid: source protocols and transport limits are missing, and the supplied mapping includes non-streaming or unsuitable items."],"refs":["R29"]},{"n":101,"batch":5,"question":"HOTSPOT (Drag and Drop is not supported)\nYou are building a data loading pattern for Fabric notebook workloads.\nYou have the following code segment.\n\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"No; No; Yes","correctAnswer":"No; No; Yes.","status":"Correct","explanation":"As in Question 76, overwrite is only the initial-create branch and MERGE is only the existing-table branch; the combined pattern supports initial plus incremental loading.","conceptArea":"Ingest/transform – Delta loading","notes":[],"refs":["R37"]},{"n":102,"batch":5,"question":"You have an Azure event hub. Each event contains the following fields:\nBikepointID\nStreet\nNeighbourhood\nLatitude\nLongitude\nNo_Bikes\nNo_Empty_Docks\nYou need to ingest the events. The solution must only retain events that have a Neighbourhood value of\nChelsea, and then store the retained events in a Fabric lakehouse.\nData retention in case of failure is required to be two days.\nWhat should you use?\n\nA. an eventstream\nB. Apache Spark Structured Streaming\nC. a streaming dataset\nD. a KQL queryset","options":[{"label":"A","text":"an eventstream"},{"label":"B","text":"Apache Spark Structured Streaming"},{"label":"C","text":"a streaming dataset"},{"label":"D","text":"a KQL queryset"}],"originalAnswer":"B","correctAnswer":"A. An eventstream.","status":"Wrong","explanation":"Eventstream directly connects to Event Hubs, filters Neighbourhood = Chelsea, writes to a lakehouse, and supports a configurable two-day retention window. The supplied explanation actually describes Eventstream even though the marked choice is Spark Structured Streaming.","conceptArea":"Ingest/transform – Real-time ingestion","notes":[],"refs":["R30","R33"]},{"n":103,"batch":5,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1.\nIn an external data source, you have data files that are 500 GB each. A new file is added every day.\nYou need to ingest the data into Lakehouse1 without applying any transformations. The solution must\nmeet the following requirements:\nTrigger the process when a new file is added.\nProvide the highest throughput.\nWhich type of item should you use to ingest the data?\n\nA. KQL queryset\nB. Streaming dataset\nC. Notebook\nD. Dataflow Gen2","options":[{"label":"A","text":"KQL queryset"},{"label":"B","text":"Streaming dataset"},{"label":"C","text":"Notebook"},{"label":"D","text":"Dataflow Gen2"}],"originalAnswer":"C","correctAnswer":"A data pipeline, which is not listed.","status":"Wrong","explanation":"The 500-GB no-transform workload requires scalable Copy activity plus a file-arrival trigger. A notebook can read data, but it is not the highest-throughput, lowest-effort event-triggered copy item; the supplied explanation acknowledges that the absent data-pipeline choice is best.","conceptArea":"Ingest/transform – Large-file ingestion","notes":["Invalid answer set: the correct Fabric item is omitted."],"refs":["R28","R35"]},{"n":104,"batch":5,"question":"What should you do to optimize the query experience for the business users?\n\nA. Enable V-Order.\nB. Create and update statistics.\nC. Run the VACUUM command.\nD. Introduce primary keys.","options":[{"label":"A","text":"Enable V-Order."},{"label":"B","text":"Create and update statistics."},{"label":"C","text":"Run the VACUUM command."},{"label":"D","text":"Introduce primary keys."}],"originalAnswer":"B","correctAnswer":"B. Create and update statistics.","status":"Correct","explanation":"Current statistics on predicate and join columns help the Fabric Warehouse optimizer choose better plans for ad-hoc queries. VACUUM is a Delta storage cleanup operation, and unenforced keys do not replace statistics.","conceptArea":"Monitor/optimize – Warehouse query performance","notes":[],"refs":["R47"]},{"n":105,"batch":5,"question":"HOTSPOT (Drag and Drop is not supported)\nYou need to troubleshoot the ad-hoc query issue.\nHow should you complete the statement? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nQuery exhibit selects last_run_start_time and last_run_command, filters last_run_total_elapsed_time_ms > 7200000, and asks for a view plus a second predicate.","options":[{"label":"A","text":"See Explanation section for answer.\n\nQuery exhibit selects last_run_start_time and last_run_command, filters last_run_total_elapsed_time_ms > 7200000, and asks for a view plus a second predicate."}],"originalAnswer":"queryinsights.long_running_queries; number_of_failed_runs > 1","correctAnswer":"FROM `queryinsights.frequently_run_queries`; AND `number_of_failed_runs > 1` (with the given two-hour last-run predicate).","status":"Wrong","explanation":"The current long_running_queries view exposes elapsed-time metrics but not number_of_failed_runs. frequently_run_queries contains both last_run_total_elapsed_time_ms and number_of_failed_runs, so it is the only offered view that can satisfy both filters.","conceptArea":"Monitor/optimize – Query Insights","notes":["Outdated schema assumption in the supplied answer."],"refs":["R39","R40"]},{"n":106,"batch":5,"question":"You need to schedule the population of the medallion layers to meet the technical requirements.\nWhat should you do?\n\nA. Schedule a data pipeline that calls other data pipelines.\nB. Schedule a notebook.\nC. Schedule an Apache Spark job.\n\nD. Schedule multiple data pipelines.","options":[{"label":"A","text":"Schedule a data pipeline that calls other data pipelines."},{"label":"B","text":"Schedule a notebook."},{"label":"C","text":"Schedule an Apache Spark job."},{"label":"D","text":"Schedule multiple data pipelines."}],"originalAnswer":"A","correctAnswer":"A. Schedule a parent data pipeline that calls other data pipelines.","status":"Correct","explanation":"A parent pipeline can sequence bronze, silver, and gold child pipelines, run independent imports in parallel, and centralize failure handling.","conceptArea":"Implement/manage – Pipeline orchestration","notes":[],"refs":["R28"]},{"n":107,"batch":5,"question":"HOTSPOT (Drag and Drop is not supported)\nYou need to ensure that the data engineers are notified if any step in populating the lakehouses fails. The\nsolution must meet the technical requirements and minimize development effort.\nWhat should you use? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"On failure; Office365Outlook activity","correctAnswer":"On failure dependency; Office 365 Outlook activity.","status":"Correct","explanation":"The On failure path runs only after an upstream failure, and the Outlook activity sends the required email with less custom development.","conceptArea":"Implement/manage – Pipeline error handling","notes":[],"refs":["R28"]},{"n":108,"batch":5,"question":"DRAG DROP (Drag and Drop is not supported)\nYou have a Fabric eventhouse that contains a KQL database. The database contains a table named\nTaxiData.\nThe following is a sample of the data in TaxiData.\n\nYou need to build two KQL queries. The solution must meet the following requirements:\nOne of the queries must partition RunningTotalAmount by VendorID.\nThe other query must create a column named FirstPickupDateTime that shows the first value of each\nhour from tpep_pickup_datetime partitioned by payment_type.\nHow should you complete each query? To answer, drag the appropriate values the correct targets. Each\nvalue may be used once, more than once, or not at all. You may need to drag the split bar between panes\nor scroll to view content.\nNote: Each correct selection is worth one point.\nSelect and Place:\n\nA. See Explanation section for answer.","options":[{"label":"A","text":"See Explanation section for answer."}],"originalAnswer":"row_cumsum; row_window_session","correctAnswer":"Statement1: row_cumsum; Statement2: row_window_session.","status":"Correct","explanation":"row_cumsum supports a restart expression when VendorID changes. row_window_session returns the first datetime in each one-hour/payment_type session as constructed by the supplied query.","conceptArea":"Ingest/transform – KQL window functions","notes":[],"refs":["R23"]},{"n":109,"batch":5,"question":"HOTSPOT (Drag and Drop is not supported)\nYou are processing streaming data from an external data provider.\nYou have the following code segment.\n\nFor each of the following statements, select Yes if the statement is true. Otherwise, select No.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nCode exhibit sorts by Location desc, UnitsSold desc, then calculates row_rank_dense(UnitsSold, prev(Location) != Location).","options":[{"label":"A","text":"See Explanation section for answer.\n\nCode exhibit sorts by Location desc, UnitsSold desc, then calculates row_rank_dense(UnitsSold, prev(Location) != Location)."}],"originalAnswer":"Yes; No; No","correctAnswer":"No; Yes; Yes.","status":"Wrong","explanation":"Descending Location order starts with Washington DC, not New York. Within Seattle, Contoso ranks 1 and tied Litware/Fabrikam rank 2; Litware is rank 1 in both San Francisco and New York, so the final two statements are true even though each partition is ranked independently.","conceptArea":"Ingest/transform – KQL ranking","notes":[],"refs":["R23"]},{"n":110,"batch":5,"question":"You have a Fabric workspace that contains a lakehouse named Lakehouse1. Lakehouse1 contains a\nDelta table named Table1.\nYou analyze Table1 and discover that Table1 contains 2,000 Parquet files of 1 MB each.\nYou need to minimize how long it takes to query Table1.\nWhat should you do?\n\nA. Disable V-Order and run the OPTIMIZE command.\nB. Disable V-Order and run the VACUUM command.\nC. Run the OPTIMIZE and VACUUM commands.","options":[{"label":"A","text":"Disable V-Order and run the OPTIMIZE command."},{"label":"B","text":"Disable V-Order and run the VACUUM command."},{"label":"C","text":"Run the OPTIMIZE and VACUUM commands."}],"originalAnswer":"C","correctAnswer":"C. Run OPTIMIZE and VACUUM.","status":"Correct","explanation":"OPTIMIZE is the operation that compacts the 2,000 small files and reduces scan overhead. VACUUM is not required for immediate query speed but is a valid accompanying cleanup; C is the only listed choice that performs OPTIMIZE without disabling V-Order.","conceptArea":"Monitor/optimize – Delta maintenance","notes":[],"refs":["R19"]},{"n":111,"batch":5,"question":"You have a Fabric workspace that contains a warehouse named Warehouse1. Data is loaded daily into\nWarehouse1 by using data pipelines and stored procedures.\nYou discover that the daily data load takes longer than expected.\nYou need to monitor Warehouse1 to identify the names of users that are actively running queries.\nWhich view should you use?\n\nA. sys.dm_exec_connections\nB. sys.dm_exec_requests\nC. queryinsights.long_running_queries\nD. queryinsights.frequently_run_queries\nE. sys.dm_exec_sessions","options":[{"label":"A","text":"sys.dm_exec_connections"},{"label":"B","text":"sys.dm_exec_requests"},{"label":"C","text":"queryinsights.long_running_queries"},{"label":"D","text":"queryinsights.frequently_run_queries"},{"label":"E","text":"sys.dm_exec_sessions"}],"originalAnswer":"E","correctAnswer":"E. sys.dm_exec_sessions.","status":"Correct","explanation":"sys.dm_exec_sessions exposes authenticated session information including login_name; filter/join with active requests when the requirement is specifically users currently running queries.","conceptArea":"Monitor/optimize – Warehouse DMVs","notes":[],"refs":["R50"]},{"n":112,"batch":5,"question":"You have a Fabric workspace that contains an eventstream named EventStream1. EventStream1 outputs\nevents to a table in a lakehouse.\nYou need to remove files that are older than seven days and are no longer in use.\nWhich command should you run?\n\nA. VACUUM\nB. COMPUTE\nC. OPTIMIZE\nD. CLONE","options":[{"label":"A","text":"VACUUM"},{"label":"B","text":"COMPUTE"},{"label":"C","text":"OPTIMIZE"},{"label":"D","text":"CLONE"}],"originalAnswer":"A","correctAnswer":"A. VACUUM.","status":"Correct","explanation":"VACUUM deletes unreferenced Delta files older than the retention threshold. The supplied example is misleading: seven days is 168 hours, not `RETAIN 7 HOURS`, and Fabric normally enforces a minimum seven-day safety check.","conceptArea":"Monitor/optimize – Delta maintenance","notes":[],"refs":["R19"]},{"n":113,"batch":5,"question":"You have a Fabric warehouse named DW1 that loads data by using a data pipeline named Pipeline1.\nPipeline1 uses a Copy data activity with a dynamic SQL source. Pipeline1 is scheduled to run every 15\nminutes.\nYou discover that Pipeline1 keeps failing.\nYou need to identify which SQL query was executed when the pipeline failed.\nWhat should you do?\n\nA. From Monitoring hub, select the latest failed run of Pipeline1, and then view the output JSON.\nB. From Monitoring hub, select the latest failed run of Pipeline1, and then view the input JSON.\n\nC. From Real-time hub, select Fabric events, and then review the details of\nMicrosoft.Fabric.ItemReadFailed.\nD. From Real-time hub, select Fabric events, and then review the details of Microsoft.\nFabric.ItemUpdateFailed.","options":[{"label":"A","text":"From Monitoring hub, select the latest failed run of Pipeline1, and then view the output JSON."},{"label":"B","text":"From Monitoring hub, select the latest failed run of Pipeline1, and then view the input JSON."},{"label":"C","text":"From Real-time hub, select Fabric events, and then review the details of\nMicrosoft.Fabric.ItemReadFailed."},{"label":"D","text":"From Real-time hub, select Fabric events, and then review the details of Microsoft.\nFabric.ItemUpdateFailed."}],"originalAnswer":"B","correctAnswer":"B. Open the failed Copy activity's input JSON in Monitoring hub.","status":"Correct","explanation":"The activity input records the resolved source configuration, including the dynamically generated SQL query. Output focuses on execution results and errors rather than the submitted query definition.","conceptArea":"Monitor/optimize – Pipeline diagnostics","notes":[],"refs":["R20"]},{"n":114,"batch":5,"question":"You have a Fabric notebook named Notebook1 that has been executing successfully for the last week.\nDuring the last run, Notebook1executed nine jobs.\nYou need to view the jobs in a timeline chart.\nWhat should you use?\n\nA. Real-Time hub\nB. Monitoring hub\nC. the job history from the application run\nD. Spark History Server\nE. the run series from the details of the application run","options":[{"label":"A","text":"Real-Time hub"},{"label":"B","text":"Monitoring hub"},{"label":"C","text":"the job history from the application run"},{"label":"D","text":"Spark History Server"},{"label":"E","text":"the run series from the details of the application run"}],"originalAnswer":"E","correctAnswer":"D. Spark History Server.","status":"Wrong","explanation":"Run series compares separate application runs over time; it does not display the nine jobs within one application as a job timeline. Spark History Server/Spark UI is the job- and stage-level interface for the completed application and provides the execution timeline/DAG views.","conceptArea":"Monitor/optimize – Spark diagnostics","notes":[],"refs":["R41","R42"]},{"n":115,"batch":5,"question":"HOTSPOT (Drag and Drop is not supported)\nYou have a Fabric workspace that contains an eventstream named EventStream1.\nYou discover that an EventStream1 transformation fails.\nYou need to find the following error information:\nThe error details, including the occurrence time\nThe total number of errors\nWhat should you use? To answer, select the appropriate options in the answer area.\nNote: Each correct selection is worth one point.\nHot Area:\n\nA. See Explanation section for answer.\n\nAnswer choices for each target are Data insights, Data preview, Details, and Runtime logs.","options":[{"label":"A","text":"See Explanation section for answer.\n\nAnswer choices for each target are Data insights, Data preview, Details, and Runtime logs."}],"originalAnswer":"Runtime logs; Details","correctAnswer":"Error details and occurrence time: Runtime logs. Total error count: Data insights.","status":"Wrong","explanation":"Runtime logs provide individual error messages and timestamps. Eventstream Data insights exposes the Runtime errors and Data conversion errors count metrics; the generic Details pane is not the documented error-count view.","conceptArea":"Monitor/optimize – Eventstream monitoring","notes":[],"refs":["R43"]},{"n":116,"batch":5,"question":"You have a Fabric workspace that contains a warehouse named Warehouse1.\nWhile monitoring Warehouse1, you discover that query performance has degraded during the last 60\nminutes.\nYou need to isolate all the queries that were run during the last 60 minutes. The results must include the\nusername of the users that submitted the queries and the query statements.\nWhat should you use?\n\nA. the Microsoft Fabric Capacity Metrics app\nB. views from the queryinsights schema\nC. Query activity\nD. the sys.dm_exec_requests dynamic management view","options":[{"label":"A","text":"the Microsoft Fabric Capacity Metrics app"},{"label":"B","text":"views from the queryinsights schema"},{"label":"C","text":"Query activity"},{"label":"D","text":"the sys.dm_exec_requests dynamic management view"}],"originalAnswer":"C","correctAnswer":"C, interpreted as the current Data Warehouse Monitor (formerly Query activity).","status":"Correct","explanation":"The portal monitor exposes recent/historical query text, submitter, and time filtering, so it can isolate the last 60 minutes without writing T-SQL. Microsoft renamed Query activity to Data Warehouse Monitor.","conceptArea":"Monitor/optimize – Warehouse monitoring","notes":["Outdated product label in the answer choice."],"refs":["R44"]},{"n":117,"batch":5,"question":"You have a Fabric workspace that contains a semantic model named Model1.\nYou need to monitor the refresh history of Model1 and visualize the refresh history in a chart.\nWhat should you use?\n\nA. the refresh history from the settings of Model1\nB. a notebook\nC. a Dataflow Gen2 dataflow\nD. a data pipeline","options":[{"label":"A","text":"the refresh history from the settings of Model1"},{"label":"B","text":"a notebook"},{"label":"C","text":"a Dataflow Gen2 dataflow"},{"label":"D","text":"a data pipeline"}],"originalAnswer":"B","correctAnswer":"B. A notebook.","status":"Correct","explanation":"A notebook using Semantic Link can retrieve refresh history programmatically and render it as a chart. The settings history is viewable but does not itself provide the requested custom charting workflow.","conceptArea":"Monitor/optimize – Semantic models","notes":[],"refs":["R22"]},{"n":118,"batch":5,"question":"You have a Fabric workspace that contains a write-intensive warehouse named DW1. DW1 stores\nstaging tables that are used to load a dimensional model. The tables are often read once, dropped, and\nthen recreated to process new data.\nYou need to minimize the load time of DW1.\n\nWhat should you do?\n\nA. Enable V-Order.\nB. Create statistics.\nC. Drop statistics.\nD. Disable V-Order.","options":[{"label":"A","text":"Enable V-Order."},{"label":"B","text":"Create statistics."},{"label":"C","text":"Drop statistics."},{"label":"D","text":"Disable V-Order."}],"originalAnswer":"D","correctAnswer":"D. Disable V-Order.","status":"Correct","explanation":"V-Order improves reads but adds write-time work. For staging tables that are write intensive, read once, dropped, and recreated, disabling it minimizes load time.","conceptArea":"Monitor/optimize – V-Order","notes":[],"refs":["R46"]}]};
